import type { MathAuthorFile, MathWeek, MathExercise, MathSkill, MathAssessment } from '../../lib/math-curriculum-types';
const b=(en:string,vi:string)=>({en,vi});
const r=String.raw;
type B=ReturnType<typeof b>;
type E={title:B;skills:MathSkill[];prompt:B;hints:B[];solution:B[];criteria:B[];errors:B[];repair:number[]};
const exercise=(week:number,index:number,e:E):MathExercise=>({id:`m2-w${String(week).padStart(3,'0')}-e${index+1}`,revision:1,title:e.title,skills:e.skills,prompt:e.prompt,hints:e.hints,solution:e.solution,rubric:e.criteria.map((criterion,i)=>({points:i===0?4:3,criterion,critical:i===0})),commonErrors:e.errors,remediation:e.repair});
const sources:MathAuthorFile['sources']=[
 {id:'a-filter',title:'Särkkä — Bayesian Filtering and Smoothing',url:'https://users.aalto.fi/~ssarkka/pub/cup_book_online_20131111.pdf',version:'2013 author-hosted online edition',access:'free official',verified:'2026-10-09',sections:'§4.3 Kalman filter; §8.2 Rauch–Tung–Striebel smoother; Appendix A.1'},
 {id:'a-prob',title:'MIT 6.436J — Fundamentals of Probability',url:'https://ocw.mit.edu/courses/6-436j-fundamentals-of-probability-fall-2018/pages/lecture-notes/',version:'Fall 2018',access:'free official',verified:'2026-10-09',sections:'Lectures 7–9 integration, 16–19 convergence/UI, 25–26 martingales; public exams as scope benchmark'},
 {id:'a-stat',title:'CMU 36-705 — Lecture 19',url:'https://stat.cmu.edu/~siva/teaching/705/lec19.pdf',version:'Fall 2019',access:'free official',verified:'2026-10-09',sections:'§19.2 support failure; §19.3 asymptotic normality; §19.4 influence functions'},
 {id:'a-convex',title:'Boyd & Vandenberghe — Convex Optimization',url:'https://web.stanford.edu/~boyd/cvxbook/',version:'2004 book; official lecture index updated 2023',access:'free official',verified:'2026-10-09',sections:'§5.1–5.5 duality/KKT; §9.3 gradient descent; §10.1 equality constraints'},
];
const weeks:MathWeek[]=[];
function add(week:number,title:B,prerequisites:number[],definitions:B,statement:B,proof:B,example:B,failure:B,items:E[],sourceId:string,section:string,mode:'study'|'assessment'|'remediation'='study'){
 const ex=items.map((e,i)=>exercise(week,i,e));const theoremId=`m2-w${String(week).padStart(3,'0')}-t1`;
 weeks.push({week,revision:1,title,level:week>=99?'graduate core':'specialization',prerequisites,
  outcomes:items.map(e=>e.title),definitions,theorems:[{id:theoremId,title,statement,proofStatus:'proved',proof,sourceId,sourceSection:section}],workedExample:example,failureCase:failure,exercises:ex,
  sessions:ex.map(e=>({title:e.title,exerciseIds:[e.id],theoremIds:[theoremId],mode,minutes:mode==='assessment'?[15,180,15,30]:[60,100,50,30],actions:mode==='assessment'?
   [b('Set a 180-minute closed-book attempt. Read the question and list allowed assumptions; do not open the theorem proof, hints or answers.', 'Chuẩn bị tự thi đóng sách 180 phút. Đọc đề và liệt kê giả thiết được dùng; không mở chứng minh, gợi ý hoặc đáp án.'),b(`Solve ${e.id}, including every requested proof and failure case. No AI or external notes.`,`Giải ${e.id}, gồm mọi chứng minh và trường hợp thất bại được hỏi. Không dùng AI hoặc ghi chú ngoài.`),b('Freeze your attempt, then compare the pointwise rubric. Mark every unsupported step.','Chốt bài làm rồi đối chiếu rubric từng bước. Đánh dấu mọi bước thiếu căn cứ.'),b('Record score, critical errors and the prerequisite to revisit; completion is not a pass.','Ghi điểm, lỗi nghiêm trọng và prerequisite cần học lại; hoàn thành không có nghĩa đạt.')]:
   [b(`Read the theorem and definitions, then reconstruct the first argument for “${e.title.en}” without the proof.`,`Đọc định nghĩa và định lý rồi tự dựng lập luận đầu của “${e.title.vi}” khi che chứng minh.`),b(`Independently solve ${e.id}; state dimensions, quantifiers and sampling assumptions.`,`Tự giải ${e.id}; ghi kích thước, lượng từ và giả thiết lấy mẫu.`),b('Compare one solution stage at a time. Repair the first invalid implication and produce a second derivation or exact small check.','Đối chiếu từng bước lời giải. Sửa suy luận sai đầu tiên rồi lập một cách dẫn xuất khác hoặc phép kiểm tra nhỏ chính xác.'),b(`Recall the proof skeleton and write why the listed failure case matters for ${e.title.en}.`,`Nhớ lại khung chứng minh và ghi vì sao trường hợp thất bại đã nêu quan trọng với ${e.title.vi}.`)],deliverable:b(`A dated proof sheet for ${e.id}, its rubric score, one invalid argument corrected, and a link to the relevant P05 proof notebook.`,`Một bản chứng minh có ngày cho ${e.id}, điểm theo rubric, một lập luận sai đã sửa và liên kết notebook chứng minh P05.`)})),
  reading:[{sourceId,section,purpose:b('Check the named theorem against the original source inside the reading block. The exercise and solution here are original and self-contained.','Đối chiếu định lý ở mục đã chỉ trong block đọc. Đề và lời giải ở đây là nguyên bản, đủ dữ kiện tự học.'),required:false}],errorChecklist:[b('Are the sigma-field, dimensions and integrability conditions stated?','Đã ghi sigma-field, kích thước và điều kiện khả tích chưa?'),b('Which convergence mode justifies each limit? Is a limit/integral or derivative/integral exchange justified?','Mỗi giới hạn dùng dạng hội tụ nào? Đổi giới hạn/tích phân hoặc đạo hàm/tích phân đã có căn cứ chưa?'),b('Does the counterexample violate exactly the hypothesis being tested?','Phản ví dụ có thực sự vi phạm giả thiết đang kiểm tra không?')],coverage:[{topic:title.en,status:'taught',evidence:ex.map(e=>e.id).join(', ')}]});
}

add(97,b('Capstone I: conditional projection and innovation geometry','Capstone I: phép chiếu có điều kiện và hình học innovation'),[36,79,80,84],
 b(r`Let $x\in\mathbb R^d$, $y\in\mathbb R^m$ be jointly Gaussian, with means $a,b$, covariance blocks $P=\operatorname{Cov}(x),C=\operatorname{Cov}(x,y),S=\operatorname{Cov}(y)$ with $S\succ0$. A prediction is measurable with respect to observations available at its timestamp. An innovation is $y-E[y\mid\mathcal F_{t-1}]$. Covariance is a matrix, not a coordinatewise variance list.`,r`Cho $x\in\mathbb R^d$, $y\in\mathbb R^m$ đồng Gaussian, trung bình $a,b$, các khối hiệp phương sai $P=\operatorname{Cov}(x),C=\operatorname{Cov}(x,y),S=\operatorname{Cov}(y)$ với $S\succ0$. Dự đoán phải đo được theo quan sát đã có tại thời điểm dự báo. Innovation là $y-E[y\mid\mathcal F_{t-1}]$. Hiệp phương sai là ma trận, không chỉ danh sách phương sai từng tọa độ.`),
 b(r`The conditional mean is $a+CS^{-1}(y-b)$ and conditional covariance is $P-CS^{-1}C^T$. It minimizes mean squared Euclidean loss among all square-integrable functions of $y$.`,r`Trung bình có điều kiện là $a+CS^{-1}(y-b)$ và hiệp phương sai có điều kiện là $P-CS^{-1}C^T$. Nó cực tiểu hóa sai số bình phương Euclid trung bình trong mọi hàm khả tích bình phương của $y$.`),
 b(r`Define $e=x-a-CS^{-1}(y-b)$. Direct covariance expansion gives $\operatorname{Cov}(e,y)=C-CS^{-1}S=0$ and $\operatorname{Cov}(e)=P-CS^{-1}C^T$. The pair $(e,y)$ is jointly Gaussian as a linear image; its characteristic function factors when the cross-covariance vanishes, hence $e$ and $y$ are independent. Thus $E[e\mid y]=0$ and the conditional covariance is the displayed constant. For any $g(y)\in L^2$, expand $x-g=e+(a+CS^{-1}(y-b)-g)$. The cross term has expectation zero by conditioning on $y$, proving the Pythagorean risk decomposition and optimality.`,r`Đặt $e=x-a-CS^{-1}(y-b)$. Khai triển hiệp phương sai cho $\operatorname{Cov}(e,y)=C-CS^{-1}S=0$ và $\operatorname{Cov}(e)=P-CS^{-1}C^T$. Cặp $(e,y)$ đồng Gaussian vì là ảnh tuyến tính; hàm đặc trưng phân tích thành tích khi hiệp phương sai chéo bằng không, nên $e$ độc lập $y$. Do đó $E[e\mid y]=0$ và hiệp phương sai có điều kiện là hằng số đã nêu. Với mọi $g(y)\in L^2$, khai triển $x-g=e+(a+CS^{-1}(y-b)-g)$. Kỳ vọng tích chéo bằng không khi lấy điều kiện theo $y$, suy ra phân rã Pythagoras của rủi ro và tính tối ưu.`),
 b(r`For $P=I_2,H=(1,1),R=2$, $S=HPH^T+R=4$, $K=PH^T/S=(1/4,1/4)^T$. With prior mean zero and $y=4$, the posterior mean is $(1,1)^T$ and covariance $\begin{pmatrix}3/4&-1/4\\-1/4&3/4\end{pmatrix}$. Its eigenvalues are $1$ and $1/2$.`,r`Với $P=I_2,H=(1,1),R=2$, $S=HPH^T+R=4$, $K=PH^T/S=(1/4,1/4)^T$. Trung bình tiên nghiệm bằng không và $y=4$ cho trung bình hậu nghiệm $(1,1)^T$, hiệp phương sai $\begin{pmatrix}3/4&-1/4\\-1/4&3/4\end{pmatrix}$. Hai trị riêng là $1$ và $1/2$.`),
 b(r`Zero covariance alone is insufficient: for symmetric $U\sim U[-1,1]$, $\operatorname{Cov}(U,U^2)=0$ but $U^2$ is determined by $U$. Without joint Gaussianity the affine predictor need not be the full conditional mean.`,r`Chỉ hiệp phương sai bằng không chưa đủ: với $U\sim U[-1,1]$ đối xứng, $\operatorname{Cov}(U,U^2)=0$ nhưng $U^2$ được xác định bởi $U$. Thiếu đồng Gaussian, dự đoán affine có thể không phải trung bình có điều kiện.`),[
 {title:b('Derive the matrix observation update','Dẫn xuất cập nhật quan sát dạng ma trận'),skills:['derivation','computation'],prompt:b(r`Take $P=\operatorname{diag}(2,1)$, $H=(1,-1)$, $R=1$, prior mean $(0,0)^T$, observation $y=2$. Derive $K$, posterior mean/covariance and prove the covariance is PSD without testing a grid.`,r`Cho $P=\operatorname{diag}(2,1)$, $H=(1,-1)$, $R=1$, trung bình tiên nghiệm $(0,0)^T$, quan sát $y=2$. Dẫn xuất $K$, trung bình/hiệp phương sai hậu nghiệm và chứng minh PSD không dùng lưới thử.`),hints:[b('Compute the scalar innovation covariance first.','Tính hiệp phương sai innovation vô hướng trước.'),b('Use a quadratic-form variance identity for PSD.','Dùng đồng nhất thức phương sai dạng toàn phương để chứng minh PSD.')],solution:[b(r`$S=2+1+1=4$ and $K=(2,-1)^T/4=(1/2,-1/4)^T$. Therefore $a^+=(1,-1/2)^T$.`,r`$S=2+1+1=4$ và $K=(2,-1)^T/4=(1/2,-1/4)^T$. Do đó $a^+=(1,-1/2)^T$.`),b(r`$P^+=P-PH^THP/4=\begin{pmatrix}1&1/2\\1/2&3/4\end{pmatrix}$. Define the posterior residual $e=x-Ky$. For any $v$, $v^TP^+v=\operatorname{Var}(v^Te)\ge0$. Here its determinant is $1/2$ and first leading minor $1$, so it is actually positive definite.`,r`$P^+=P-PH^THP/4=\begin{pmatrix}1&1/2\\1/2&3/4\end{pmatrix}$. Định nghĩa phần dư hậu nghiệm $e=x-Ky$. Với mọi $v$, $v^TP^+v=\operatorname{Var}(v^Te)\ge0$. Ở đây định thức bằng $1/2$ và minor đầu bằng $1$, nên thực ra xác định dương.`),b('A stable implementation solves S times K-transpose = H P. For matrix S use Cholesky solves, never form its inverse explicitly.','Cài đặt ổn định giải S nhân K-chuyển vị = H P. Với S ma trận, dùng phép giải Cholesky, không tạo nghịch đảo tường minh.')],criteria:[b('Correct S, gain dimensions and mean.','S, kích thước gain và trung bình đúng.'),b('Correct full covariance including cross terms.','Đúng toàn bộ hiệp phương sai, gồm phần tử chéo.'),b('General PSD argument and stable-solve distinction.','Lập luận PSD tổng quát và phân biệt phép giải ổn định.')],errors:[b('Dropping the off-diagonal covariance destroys the update geometry.','Bỏ hiệp phương sai ngoài đường chéo làm sai hình học cập nhật.')],repair:[7,36,79]},
 {title:b('Prove the conditional risk identity','Chứng minh đồng nhất thức rủi ro có điều kiện'),skills:['proof'],prompt:b(r`For $X\in L^2(\mathbb R^d)$ and a sigma-field $\mathcal G$, let $m=E[X\mid\mathcal G]$. Prove $E\|X-g\|^2=E\|X-m\|^2+E\|m-g\|^2$ for every $\mathcal G$-measurable $g\in L^2$. Explain why uniqueness is only a.s.`,r`Với $X\in L^2(\mathbb R^d)$ và sigma-field $\mathcal G$, đặt $m=E[X\mid\mathcal G]$. Chứng minh $E\|X-g\|^2=E\|X-m\|^2+E\|m-g\|^2$ cho mọi $g\in L^2$ đo được theo $\mathcal G$. Giải thích vì sao chỉ duy nhất hầu chắc chắn.`),hints:[b('First prove orthogonality against bounded measurable functions.','Trước hết chứng minh trực giao với hàm đo được bị chặn.'),b('Truncate each component of m-g, then use Cauchy–Schwarz.','Cắt cụt từng tọa độ m-g rồi dùng Cauchy–Schwarz.')],solution:[b(r`The defining CE identity gives $E[(X_j-m_j)h]=0$ for bounded $\mathcal G$-measurable simple $h$, then bounded $h$ by dominated approximation. Conditional Jensen gives $m\in L^2$.`,r`Định nghĩa CE cho $E[(X_j-m_j)h]=0$ với $h$ đơn đo được theo $\mathcal G$, bị chặn, rồi mở rộng sang $h$ bị chặn bằng xấp xỉ bị trội. Jensen có điều kiện cho $m\in L^2$.`),b(r`Set $h_N=\max(-N,\min(m_j-g_j,N))$. It converges in $L^2$ to $m_j-g_j$; Cauchy–Schwarz transfers orthogonality. Sum over $j$ and expand the square to obtain the identity.`,r`Đặt $h_N=\max(-N,\min(m_j-g_j,N))$. Nó hội tụ trong $L^2$ tới $m_j-g_j$; Cauchy–Schwarz chuyển tính trực giao sang giới hạn. Cộng theo $j$ và khai triển bình phương thu được đồng nhất thức.`),b(r`Equal minimum risk forces $E\|m-g\|^2=0$, hence $m=g$ a.s. Changing a function on a measurable null set does not change risk or any defining integral, so pointwise uniqueness is unjustified.`,r`Rủi ro cực tiểu bằng nhau buộc $E\|m-g\|^2=0$, nên $m=g$ hầu chắc chắn. Đổi giá trị trên tập đo được có xác suất không không đổi rủi ro hay tích phân định nghĩa; không được khẳng định duy nhất từng điểm.`)],criteria:[b('Integrability and measurable projection space specified.','Ghi tính khả tích và không gian chiếu đo được.'),b('Truncation extends bounded orthogonality legitimately.','Cắt cụt mở rộng trực giao bị chặn hợp lệ.'),b('Square expansion and a.s. uniqueness correctly concluded.','Khai triển bình phương và kết luận duy nhất hầu chắc chắn đúng.')],errors:[b('Pulling out an unbounded random variable without checking integrability is a gap.','Đưa biến ngẫu nhiên không bị chặn ra ngoài mà không kiểm tra khả tích là thiếu bước.')],repair:[33,35,36]},
 {title:b('Show innovations are orthogonal over time','Chứng minh innovation trực giao theo thời gian'),skills:['proof','transfer'],prompt:b(r`Let $Y_t\in L^2$ be adapted to $\mathcal F_t$ and $e_t=Y_t-E[Y_t\mid\mathcal F_{t-1}]$. Prove $E[e_t e_s]=0$ for $s<t$. Does this prove independence? Give an adapted uncorrelated but dependent pair.`,r`Cho $Y_t\in L^2$ thích nghi với $\mathcal F_t$ và $e_t=Y_t-E[Y_t\mid\mathcal F_{t-1}]$. Chứng minh $E[e_t e_s]=0$ khi $s<t$. Có suy ra độc lập không? Cho một cặp thích nghi không tương quan nhưng phụ thuộc.`),hints:[b('Condition on the larger past sigma-field.','Lấy điều kiện theo sigma-field quá khứ lớn hơn.'),b('Use a random sign and a previous random scale.','Dùng dấu ngẫu nhiên và thang đo ngẫu nhiên ở quá khứ.')],solution:[b(r`$e_s$ is $\mathcal F_s\subseteq\mathcal F_{t-1}$-measurable and $E[e_t\mid\mathcal F_{t-1}]=0$. The product is integrable by Cauchy–Schwarz; conditional pull-out yields $E[e_te_s]=0$.`,r`$e_s$ đo được theo $\mathcal F_s\subseteq\mathcal F_{t-1}$ và $E[e_t\mid\mathcal F_{t-1}]=0$. Tích khả tích nhờ Cauchy–Schwarz; tính đưa ra ngoài kỳ vọng có điều kiện cho $E[e_te_s]=0$.`),b(r`Let $U$ take $1,-1,2,-2$ equally and let $V$ be an independent fair sign. Set $e_1=U$, $e_2=UV$ with $\mathcal F_1=\sigma(U)$ and $\mathcal F_2=\sigma(U,V)$. Both means are zero; $E[e_2\mid\mathcal F_1]=0$.`,r`Cho $U$ nhận $1,-1,2,-2$ đồng xác suất và $V$ là dấu công bằng độc lập. Đặt $e_1=U$, $e_2=UV$, $\mathcal F_1=\sigma(U)$, $\mathcal F_2=\sigma(U,V)$. Cả hai trung bình bằng không; $E[e_2\mid\mathcal F_1]=0$.`),b(r`They are dependent because $|e_2|=|e_1|$: the event of magnitude 2 has joint probability $1/2$, not $1/4$. Martingale differences need not be independent or identically distributed.`,r`Chúng phụ thuộc vì $|e_2|=|e_1|$: biến cố độ lớn bằng 2 có xác suất đồng thời $1/2$, không phải $1/4$. Hiệu martingale không nhất thiết độc lập hoặc cùng phân phối.`)],criteria:[b('Correct filtration nesting; product integrable.','Đúng quan hệ lồng filtration; tích khả tích.'),b('Orthogonality derived using conditional expectation.','Dẫn xuất trực giao bằng kỳ vọng có điều kiện.'),b('Valid dependence counterexample with conditional mean zero.','Phản ví dụ phụ thuộc hợp lệ với trung bình có điều kiện bằng không.')],errors:[b('Uncorrelated innovations are not an IID test.','Innovation không tương quan không phải phép xác nhận IID.')],repair:[36,43,80]},
 {title:b('Diagnose an unobservable state','Chẩn đoán trạng thái không quan sát được'),skills:['counterexample','derivation'],prompt:b(r`Take $A=\operatorname{diag}(0.8,1.1)$, $H=(1,0)$, diagonal initial covariance with $P_{0,22}>0$ and independent diagonal Gaussian process noise. Observations are $y_t=Hx_t+v_t$ with independent Gaussian observation noise of positive variance. Show why observing arbitrarily many $y_t$ cannot reduce uncertainty in the second coordinate. Contrast with $H=(1,1)$ by calculating the two-step observability rank.`,r`Cho $A=\operatorname{diag}(0.8,1.1)$, $H=(1,0)$, hiệp phương sai đầu chéo với $P_{0,22}>0$ và nhiễu quá trình Gaussian chéo độc lập. Quan sát là $y_t=Hx_t+v_t$ với nhiễu quan sát Gaussian độc lập có phương sai dương. Chứng minh quan sát nhiều $y_t$ tùy ý không giảm bất định tọa độ hai. So sánh $H=(1,1)$ bằng hạng quan sát hai bước.`),hints:[b('The second gain coordinate stays zero by induction.','Tọa độ gain thứ hai luôn bằng không theo quy nạp.'),b('Stack H and HA.','Chồng H và HA.')],solution:[b(r`Diagonal propagation and $H=(1,0)$ keep cross covariance zero. Hence $K_2=0$ for every update. The second variance obeys $p_{2,t}=1.1^2p_{2,t-1}+q_2$ with no measurement reduction.`,r`Lan truyền chéo và $H=(1,0)$ giữ hiệp phương sai chéo bằng không. Vì thế $K_2=0$ ở mọi lần cập nhật. Phương sai thứ hai theo $p_{2,t}=1.1^2p_{2,t-1}+q_2$, không được quan sát làm giảm.`),b(r`The observability matrix for the first H has rows $(1,0),(0.8,0)$ and rank 1. For $H=(1,1)$ it is $\begin{pmatrix}1&1\\0.8&1.1\end{pmatrix}$, determinant $0.3$, rank 2.`,r`Ma trận quan sát của H đầu có các hàng $(1,0),(0.8,0)$, hạng 1. Với $H=(1,1)$ nó là $\begin{pmatrix}1&1\\0.8&1.1\end{pmatrix}$, định thức $0.3$, hạng 2.`),b('Full observability permits information about both coordinates but does not make finite noisy observations exact. Parameter identifiability is a separate issue from observability of a known state model.','Quan sát đầy đủ cho phép có thông tin về cả hai tọa độ nhưng không biến quan sát nhiễu hữu hạn thành chính xác. Nhận dạng tham số là vấn đề khác tính quan sát của mô hình trạng thái đã biết.')],criteria:[b('Correct induction for gain and variance.','Quy nạp gain và phương sai đúng.'),b('Both rank calculations correct.','Tính đúng cả hai hạng.'),b('Distinguishes observability, exact recovery and identifiability.','Phân biệt tính quan sát, khôi phục chính xác và nhận dạng.')],errors:[b('More samples do not recover a completely unobserved independent coordinate.','Thêm mẫu không khôi phục tọa độ độc lập hoàn toàn không được quan sát.')],repair:[6,79,81]},
 {title:b('Construct a timestamp-safe capstone contract','Lập điều kiện capstone đúng thời điểm'),skills:['transfer','proof'],prompt:b(r`Your target is $Y_{t+1}$; observed data at origin t generate $\mathcal F_t$. A smoother estimates $x_t$ using $Y_{1:T}$, $T>t$. Prove why this is not generally an admissible forecasting feature, and specify an admissible Kalman predictor with a paired evaluation estimand.`,r`Mục tiêu là $Y_{t+1}$; dữ liệu tại gốc t sinh $\mathcal F_t$. Smoother ước lượng $x_t$ bằng $Y_{1:T}$, $T>t$. Chứng minh vì sao nói chung đây không phải đặc trưng dự báo hợp lệ, và nêu dự báo Kalman hợp lệ cùng đại lượng so sánh cặp.`),hints:[b('Admissibility is measurability, not correlation size.','Tính hợp lệ là tính đo được, không phải độ lớn tương quan.')],solution:[b(r`A forecast must be $\mathcal F_t$-measurable. With $Y_{t+1}=x_t+v$ and nondegenerate independent Gaussian $x_t,v$, the smoother uses a nonzero multiple of $Y_{t+1}$, which is not $\mathcal F_t$-measurable; it has conditional variance above zero.`,r`Dự báo phải đo được theo $\mathcal F_t$. Với $Y_{t+1}=x_t+v$ và $x_t,v$ Gaussian độc lập không suy biến, smoother dùng bội khác không của $Y_{t+1}$, không đo được theo $\mathcal F_t$ vì có phương sai có điều kiện dương.`),b(r`Use $\hat Y_{t+1|t}=HA m_{t|t}$, with parameters fitted only using information available before the evaluation origin. Record parameter-update timestamps, target-release timestamps and any adaptive choices.`,r`Dùng $\hat Y_{t+1|t}=HA m_{t|t}$, với tham số chỉ fit bằng thông tin có trước gốc đánh giá. Ghi thời điểm cập nhật tham số, thời điểm nhãn được công bố và mọi lựa chọn thích nghi.`),b(r`Evaluate paired $d_t=(Y_{t+1}-\hat Y^{KF}_{t+1|t})^2-(Y_{t+1}-\hat Y^{base}_{t+1|t})^2$ on identical origins. The target is $E[d_t]$ under a declared stationary regime, or the finite-period average if stationarity is unjustified. Use dependent uncertainty, not IID row resampling.`,r`Đánh giá cặp $d_t=(Y_{t+1}-\hat Y^{KF}_{t+1|t})^2-(Y_{t+1}-\hat Y^{base}_{t+1|t})^2$ trên cùng các gốc. Đích là $E[d_t]$ trong chế độ dừng đã nêu, hoặc trung bình giai đoạn hữu hạn nếu không có căn cứ dừng. Dùng bất định có phụ thuộc, không bootstrap từng hàng IID.`)],criteria:[b('Explains nonmeasurability and does not use future observations.','Giải thích không đo được và không dùng quan sát tương lai.'),b('Constructs an adapted predictor and timestamp record.','Dựng dự báo thích nghi và bản ghi thời điểm.'),b('Defines paired estimand and its stationarity boundary.','Định nghĩa đại lượng cặp và giới hạn giả thiết dừng.')],errors:[b('A low holdout loss cannot legalize future information.','Loss holdout thấp không làm thông tin tương lai trở nên hợp lệ.')],repair:[43,78,81,82]},
 ],'a-filter','§4.3; §8.2; Appendix A.1');

add(98,b('Capstone II: dependent uncertainty and calibration','Capstone II: bất định phụ thuộc và hiệu chuẩn'),[73,76,77,80,82,97],
 b(r`For a real weakly stationary sequence $(D_t)$ write $\mu=E D_t$, $\gamma_h=\operatorname{Cov}(D_t,D_{t-h})$, $\bar D_n=n^{-1}\sum_{t=1}^nD_t$. Long-run variance is $\Omega=\sum_{h=-\infty}^{\infty}\gamma_h$ when absolutely convergent. Variance convergence alone is not a CLT.`,r`Với chuỗi thực dừng yếu $(D_t)$, đặt $\mu=E D_t$, $\gamma_h=\operatorname{Cov}(D_t,D_{t-h})$, $\bar D_n=n^{-1}\sum_{t=1}^nD_t$. Phương sai dài hạn là $\Omega=\sum_{h=-\infty}^{\infty}\gamma_h$ khi tổng hội tụ tuyệt đối. Hội tụ phương sai tự nó không phải CLT.`),
 b(r`If $\sum_h|\gamma_h|<\infty$, then $n\operatorname{Var}(\bar D_n)=\gamma_0+2\sum_{h=1}^{n-1}(1-h/n)\gamma_h\to\Omega\ge0$.`,r`Nếu $\sum_h|\gamma_h|<\infty$, thì $n\operatorname{Var}(\bar D_n)=\gamma_0+2\sum_{h=1}^{n-1}(1-h/n)\gamma_h\to\Omega\ge0$.`),
 b(r`Expand the variance of the sum as $\sum_{s,t}\gamma_{s-t}$. There are n diagonal terms and $n-h$ ordered pairs in each direction at lag h. Divide by n to get the finite formula. For a cutoff M, the finite h≤M weights converge to 1, while the absolute tail error is at most $2\sum_{h>M}|\gamma_h|$ for either weighted or unweighted tails. First send n to infinity, then M to infinity. Nonnegativity follows because each finite variance is nonnegative. This proof yields no distributional limit without an additional dependent CLT.`,r`Khai triển phương sai tổng thành $\sum_{s,t}\gamma_{s-t}$. Có n phần tử chéo và $n-h$ cặp theo mỗi hướng ở lag h. Chia cho n thu công thức hữu hạn. Với ngưỡng M, các trọng số h≤M hội tụ tới 1, còn sai số đuôi tuyệt đối được chặn bởi $2\sum_{h>M}|\gamma_h|$ cho cả đuôi có và không trọng số. Cho n tiến vô hạn trước, rồi M tiến vô hạn. Tính không âm do mọi phương sai hữu hạn không âm. Chứng minh này không cho giới hạn phân phối nếu thiếu CLT phụ thuộc riêng.`),
 b(r`For stationary $D_t=\rho D_{t-1}+\epsilon_t$, $|\rho|<1$, IID mean-zero innovations with variance $\sigma^2$, $\gamma_0=\sigma^2/(1-\rho^2)$ and $\Omega=\sigma^2/(1-\rho)^2$. With $\rho=1/2,\sigma^2=3$, these are 4 and 12. IID standard errors understate uncertainty by an asymptotic factor $\sqrt3$.`,r`Với $D_t=\rho D_{t-1}+\epsilon_t$ dừng, $|\rho|<1$, innovation IID trung bình không phương sai $\sigma^2$, ta có $\gamma_0=\sigma^2/(1-\rho^2)$ và $\Omega=\sigma^2/(1-\rho)^2$. Với $\rho=1/2,\sigma^2=3$, hai giá trị là 4 và 12. SE IID đánh giá thấp bất định với hệ số tiệm cận $\sqrt3$.`),
 b(r`Let $D_t=Z$ for every t, where $\operatorname{Var}(Z)=1$. This is strictly stationary but $\operatorname{Var}(\bar D_n)=1$; $\gamma_h=1$ is not summable. Sample size alone does not produce concentration.`,r`Cho $D_t=Z$ ở mọi t với $\operatorname{Var}(Z)=1$. Chuỗi dừng chặt nhưng $\operatorname{Var}(\bar D_n)=1$; $\gamma_h=1$ không khả tổng. Tăng số mẫu tự nó không tạo tập trung.`),[
 {title:b('AR uncertainty versus IID uncertainty','Bất định AR so với IID'),skills:['derivation','computation'],prompt:b(r`For a stationary AR(1) with $\rho=-1/2$, innovation variance 3, derive $\gamma_h$ and $\Omega$. Calculate the exact $n=3$ variance of the average. Explain why negative serial correlation can reduce the long-run variance.`,r`Với AR(1) dừng có $\rho=-1/2$, phương sai innovation 3, dẫn xuất $\gamma_h$ và $\Omega$. Tính chính xác phương sai trung bình khi $n=3$. Giải thích vì sao tương quan nối tiếp âm có thể giảm phương sai dài hạn.`),hints:[b('Use the causal series and then count covariance pairs.','Dùng chuỗi nhân quả rồi đếm cặp hiệp phương sai.')],solution:[b(r`Causality gives $D_t=\sum_{j\ge0}\rho^j\epsilon_{t-j}$ in $L^2$; independent innovations imply $\gamma_h=3\rho^{|h|}/(1-\rho^2)=4(-1/2)^{|h|}$.`,r`Tính nhân quả cho $D_t=\sum_{j\ge0}\rho^j\epsilon_{t-j}$ trong $L^2$; innovation độc lập suy ra $\gamma_h=3\rho^{|h|}/(1-\rho^2)=4(-1/2)^{|h|}$.`),b(r`$\Omega=3/(1+1/2)^2=4/3$. At n=3, $\operatorname{Var}(\bar D_3)=[3(4)+2(2(-2)+1)]/9=2/3$.`,r`$\Omega=3/(1+1/2)^2=4/3$. Với n=3, $\operatorname{Var}(\bar D_3)=[3(4)+2(2(-2)+1)]/9=2/3$.`),b(r`Negative odd-lag covariance offsets positive even-lag covariance. $\Omega/n$ is asymptotic, not the exact finite-n value: $4/9\ne2/3$.`,r`Hiệp phương sai âm ở lag lẻ bù hiệp phương sai dương ở lag chẵn. $\Omega/n$ là tiệm cận, không phải giá trị hữu hạn chính xác: $4/9\ne2/3$.`)],criteria:[b('Causal representation and covariance justified.','Giải thích biểu diễn nhân quả và hiệp phương sai.'),b('Correct exact and asymptotic variances.','Đúng phương sai chính xác và tiệm cận.'),b('Distinguishes finite-n from limiting variance.','Phân biệt phương sai hữu hạn và giới hạn.')],errors:[b('Replacing all off-diagonal entries by zero gives the wrong answer.','Thay mọi phần tử ngoài đường chéo bằng không làm sai đáp án.')],repair:[74,75,77]},
 {title:b('Prove paired comparisons need paired covariance','Chứng minh so sánh cặp cần hiệp phương sai cặp'),skills:['proof','transfer'],prompt:b(r`For jointly stationary loss streams A and B, define $D_t=A_t-B_t$. Derive its lag covariance in terms of four cross-covariances. Construct A=B with nonzero variance and explain why independently bootstrapping the streams is invalid for the paired target.`,r`Với hai chuỗi loss A và B dừng đồng thời, đặt $D_t=A_t-B_t$. Dẫn xuất hiệp phương sai lag bằng bốn hiệp phương sai chéo. Dựng A=B với phương sai khác không và giải thích vì sao bootstrap độc lập hai chuỗi sai cho mục tiêu cặp.`),hints:[b('Expand both factors before summing lags.','Khai triển cả hai thừa số trước khi cộng lag.')],solution:[b(r`$\gamma_D(h)=\gamma_A(h)+\gamma_B(h)-\operatorname{Cov}(A_t,B_{t-h})-\operatorname{Cov}(B_t,A_{t-h})$. The two cross terms need not be equal for fixed positive h.`,r`$\gamma_D(h)=\gamma_A(h)+\gamma_B(h)-\operatorname{Cov}(A_t,B_{t-h})-\operatorname{Cov}(B_t,A_{t-h})$. Hai số hạng chéo không nhất thiết bằng nhau tại một h dương cố định.`),b(r`Set $A_t=B_t=Z_t^2$ for IID standard normal $Z_t$. Each loss has variance 2, but $D_t=0$ identically; its uncertainty is zero. Independent resampling creates unequal artificial pairs and positive variance.`,r`Đặt $A_t=B_t=Z_t^2$ với $Z_t$ chuẩn tắc IID. Mỗi loss có phương sai 2, nhưng $D_t=0$ đồng nhất, bất định bằng không. Lấy mẫu lại độc lập tạo cặp giả không bằng nhau và phương sai dương.`),b('Resample aligned vectors (A_t,B_t), using common time blocks when serial dependence matters, or analyze D directly with a justified HAC procedure. A block choice does not by itself establish asymptotic validity.','Lấy mẫu lại vector ghép (A_t,B_t), dùng block thời gian chung khi có phụ thuộc nối tiếp, hoặc phân tích D trực tiếp bằng HAC có căn cứ. Chỉ chọn block chưa tự bảo đảm tính hợp lệ tiệm cận.')],criteria:[b('All four covariance terms retained with correct lags.','Giữ đủ bốn số hạng hiệp phương sai đúng lag.'),b('Exact A=B counterexample derived.','Dẫn xuất chính xác phản ví dụ A=B.'),b('Correct resampling unit and dependence qualification.','Đúng đơn vị lấy mẫu lại và điều kiện phụ thuộc.')],errors:[b('Matching date ranges is insufficient if resampling breaks the pairing.','Cùng khoảng ngày chưa đủ nếu lấy mẫu lại làm mất ghép cặp.')],repair:[52,77,78]},
 {title:b('Boundary case: the random walk average','Trường hợp biên: trung bình random walk'),skills:['derivation','counterexample'],prompt:b(r`Let $X_t=\sum_{j=1}^t\epsilon_j$ with IID mean-zero variance-one innovations. Derive $\operatorname{Var}(n^{-1}\sum_{t=1}^nX_t)$ exactly. Why is a stationary HAC interval for a fixed mean inappropriate?`,r`Cho $X_t=\sum_{j=1}^t\epsilon_j$ với innovation IID trung bình không phương sai một. Dẫn xuất chính xác $\operatorname{Var}(n^{-1}\sum_{t=1}^nX_t)$. Vì sao khoảng HAC dừng cho một trung bình cố định không phù hợp?`),hints:[b('Reverse the finite sums; each innovation has a different multiplicity.','Đổi thứ tự tổng hữu hạn; mỗi innovation có số lần xuất hiện khác nhau.')],solution:[b(r`$\bar X_n=n^{-1}\sum_{j=1}^n(n-j+1)\epsilon_j$. Independence yields $\operatorname{Var}(\bar X_n)=n^{-2}\sum_{k=1}^nk^2$.`,r`$\bar X_n=n^{-1}\sum_{j=1}^n(n-j+1)\epsilon_j$. Độc lập cho $\operatorname{Var}(\bar X_n)=n^{-2}\sum_{k=1}^nk^2$.`),b(r`The sum is $n(n+1)(2n+1)/6$, so variance equals $(n+1)(2n+1)/(6n)\sim n/3$, not $O(1/n)$. Moreover $\operatorname{Var}(X_t)=t$, so weak stationarity fails.`,r`Tổng bằng $n(n+1)(2n+1)/6$, nên phương sai là $(n+1)(2n+1)/(6n)\sim n/3$, không phải $O(1/n)$. Hơn nữa $\operatorname{Var}(X_t)=t$, nên không dừng yếu.`),b('Differencing yields stationary innovations under this model, but changes the estimand from level to increment. Do not report a stationary level interval merely because software returns one.','Lấy sai phân cho innovation dừng theo mô hình này nhưng đổi đại lượng đích từ mức sang gia số. Không báo khoảng dừng cho mức chỉ vì phần mềm xuất được nó.')],criteria:[b('Correct innovation weights and independence use.','Đúng trọng số innovation và cách dùng độc lập.'),b('Exact polynomial variance and rate.','Đúng phương sai đa thức và tốc độ.'),b('Identifies failed stationarity and changed estimand after differencing.','Chỉ ra mất tính dừng và đổi đại lượng đích khi sai phân.')],errors:[b('A unit root is not a nearly IID process.','Nghiệm đơn vị không phải quá trình gần IID.')],repair:[73,74,76]},
 {title:b('Innovation likelihood and misspecification','Likelihood innovation và sai mô hình'),skills:['derivation','application'],prompt:b(r`Under a correctly specified linear Gaussian model, observations have one-step means $\hat y_t$ and positive definite covariances $S_t$. Derive the joint log likelihood using innovations $v_t=y_t-\hat y_t$. Explain why adapting Q using the current v before scoring that v invalidates the stated predictive density.`,r`Dưới mô hình tuyến tính Gaussian đúng, quan sát có trung bình một bước $\hat y_t$ và hiệp phương sai xác định dương $S_t$. Dẫn xuất log likelihood đồng thời qua innovation $v_t=y_t-\hat y_t$. Giải thích vì sao chỉnh Q theo v hiện tại trước khi chấm chính v ấy làm sai mật độ dự báo đã nêu.`),hints:[b('Factor the joint density into conditional densities.','Phân tích mật độ đồng thời thành các mật độ có điều kiện.')],solution:[b(r`The chain rule gives $p(y_{1:T})=\prod_t p(y_t\mid y_{1:t-1})$. Each factor is $N(\hat y_t,S_t)$, hence $\ell=-\frac12\sum_t[m\log(2\pi)+\log\det S_t+v_t^TS_t^{-1}v_t]$.`,r`Quy tắc chuỗi cho $p(y_{1:T})=\prod_t p(y_t\mid y_{1:t-1})$. Mỗi thừa số là $N(\hat y_t,S_t)$, nên $\ell=-\frac12\sum_t[m\log(2\pi)+\log\det S_t+v_t^TS_t^{-1}v_t]$.`),b('Compute the quadratic form by a Cholesky solve and log determinant from its positive diagonal. The dimension m appears in the normalization; covariance scaling cannot be dropped.','Tính dạng toàn phương bằng phép giải Cholesky, log định thức từ đường chéo dương. Kích thước m xuất hiện trong hằng số chuẩn hóa; không được bỏ tỷ lệ hiệp phương sai.'),b(r`A density $p(y_t\mid\mathcal F_{t-1})$ fixes parameters before $y_t$ is observed. A Q chosen using $v_t$ generally produces a function of $y_t$ that need not integrate to one. Update Q for the next prediction, or explicitly derive a different joint model.`,r`Mật độ $p(y_t\mid\mathcal F_{t-1})$ cố định tham số trước khi thấy $y_t$. Q chọn bằng $v_t$ thường tạo hàm của $y_t$ không nhất thiết tích phân bằng một. Cập nhật Q cho dự báo tiếp, hoặc dẫn xuất rõ mô hình đồng thời khác.`)],criteria:[b('Correct conditional density factorization and timing.','Phân tích mật độ có điều kiện và thời điểm đúng.'),b('All likelihood terms and dimensions correct.','Đúng mọi số hạng likelihood và kích thước.'),b('Stable calculation and current-outcome adaptation failure explained.','Giải thích phép tính ổn định và lỗi thích nghi bằng kết quả hiện tại.')],errors:[b('Retrofitting uncertainty to the same residual creates an invalid score.','Chỉnh bất định theo chính residual đang chấm tạo score không hợp lệ.')],repair:[45,69,80]},
 {title:b('Separate calibration from a profitable forecast claim','Tách hiệu chuẩn khỏi kết luận lợi nhuận dự báo'),skills:['proof','transfer'],prompt:b(r`If the Gaussian predictive model is correct and $S_t\succ0$, show $E[v_t^TS_t^{-1}v_t\mid\mathcal F_{t-1}]=m$. Give a model with this expectation but incorrect Gaussian tails. Specify what the capstone may claim from checking this moment alone.`,r`Nếu mô hình dự báo Gaussian đúng và $S_t\succ0$, chứng minh $E[v_t^TS_t^{-1}v_t\mid\mathcal F_{t-1}]=m$. Cho mô hình có kỳ vọng này nhưng đuôi không Gaussian. Nêu capstone có thể kết luận gì chỉ từ kiểm tra moment ấy.`),hints:[b('Use the trace identity for a quadratic form.','Dùng đồng nhất thức trace của dạng toàn phương.')],solution:[b(r`Conditionally $E[v_t]=0$ and $E[v_tv_t^T]=S_t$. Thus $E[v_t^TS_t^{-1}v_t\mid\mathcal F_{t-1}]=\operatorname{tr}(S_t^{-1}S_t)=m$. Gaussianity is not needed for this expectation, only the stated first two moments.`,r`Có điều kiện, $E[v_t]=0$ và $E[v_tv_t^T]=S_t$. Vì thế $E[v_t^TS_t^{-1}v_t\mid\mathcal F_{t-1}]=\operatorname{tr}(S_t^{-1}S_t)=m$. Kỳ vọng này chỉ cần hai moment đã nêu, không cần Gaussian.`),b(r`For m=1 take an independent fair sign v=±1 and S=1. The statistic is always 1, whereas under a standard Gaussian it has a $\chi_1^2$ distribution. Correct mean alone does not establish the reference distribution or tail coverage.`,r`Với m=1 lấy v=±1 là dấu công bằng độc lập, S=1. Thống kê luôn bằng 1, còn dưới chuẩn tắc nó có phân phối $\chi_1^2$. Chỉ trung bình đúng không xác nhận phân phối tham chiếu hay độ phủ đuôi.`),b('Report a conditional second-moment diagnostic under the specified generator, with finite-sample uncertainty. It neither establishes all calibration nor market profitability; those need separate assumptions, targets and data.','Báo đây là chẩn đoán moment bậc hai có điều kiện dưới bộ sinh đã nêu, kèm bất định mẫu hữu hạn. Nó không xác nhận mọi dạng hiệu chuẩn hay lợi nhuận thị trường; cần giả thiết, đại lượng đích và dữ liệu riêng.')],criteria:[b('Correct conditional trace argument.','Lập luận trace có điều kiện đúng.'),b('Counterexample meets mean condition but differs in distribution.','Phản ví dụ thỏa moment nhưng khác phân phối.'),b('Precisely limited scientific claim.','Giới hạn kết luận khoa học chính xác.')],errors:[b('An average diagnostic equal to its target is not a proof of calibration.','Trung bình chẩn đoán bằng đích không phải chứng minh hiệu chuẩn.')],repair:[33,80,82]},
 ],'a-filter','§4.3 predictive innovation; §12.3 innovation likelihood; original dependent variance derivation');

const finalDefinition=b(r`This is a four-part self-examination, one 180-minute attempt per day, inside 240-minute sessions. Allowed results: IID LLN/CLT, dominated convergence, CE existence, Gaussian characteristic functions, and basic spectral theory. Every other requested implication must be proved. $\mathcal G\subseteq\mathcal H$ denotes nested sigma-fields; equality of random variables is a.s. unless stated otherwise.`,r`Đây là kỳ tự thi bốn phần, mỗi ngày làm một phần trong 180 phút, nằm trong buổi 240 phút. Được dùng LLN/CLT IID, hội tụ bị trội, tồn tại CE, hàm đặc trưng Gaussian và lý thuyết phổ cơ bản. Phải chứng minh mọi suy luận khác mà đề yêu cầu. $\mathcal G\subseteq\mathcal H$ chỉ sigma-field lồng nhau; đẳng thức biến ngẫu nhiên hiểu là hầu chắc chắn trừ khi nói khác.`);
const finalStatement=b(r`For nonnegative errors $Z_n\to0$ in probability and $\sup_nE Z_n^2\le C<\infty$, $E Z_n\to0$. This is a reusable uniform-integrability implication, not a normal approximation.`,r`Với sai số không âm $Z_n\to0$ theo xác suất và $\sup_nE Z_n^2\le C<\infty$, ta có $E Z_n\to0$. Đây là hệ quả khả tích đều có thể tái dùng, không phải xấp xỉ chuẩn.`);
const finalProof=b(r`For any $\epsilon>0$, split at $Z_n\le\epsilon$. The first expectation is at most $\epsilon$ and Cauchy–Schwarz bounds the remainder by $\sqrt C\sqrt{P(Z_n>\epsilon)}$. Taking limsup gives at most $\epsilon$, then send $\epsilon\downarrow0$. The uniform second-moment bound is essential to this argument.`,r`Với mọi $\epsilon>0$, tách tại $Z_n\le\epsilon$. Kỳ vọng phần đầu không quá $\epsilon$, Cauchy–Schwarz chặn phần còn lại bởi $\sqrt C\sqrt{P(Z_n>\epsilon)}$. Lấy limsup được không quá $\epsilon$, rồi cho $\epsilon\downarrow0$. Cận moment bậc hai đồng đều là thiết yếu trong lập luận này.`);
const finalExample=b(r`If $Z_n=|\bar X_n-\mu|$ for IID variables with variance $\sigma^2$, $E Z_n\le\sigma/\sqrt n$. This supplies a rate absent from bare convergence in probability.`,r`Nếu $Z_n=|\bar X_n-\mu|$ với biến IID phương sai $\sigma^2$, thì $E Z_n\le\sigma/\sqrt n$. Đây là tốc độ không có từ riêng hội tụ theo xác suất.`);
const finalFailure=b(r`For $U\sim U(0,1)$, $Z_n=n1_{\{U<1/n\}}\to0$ a.s. but $E Z_n=1$ and $E Z_n^2=n$. Pointwise disappearance does not control rare large values.`,r`Với $U\sim U(0,1)$, $Z_n=n1_{\{U<1/n\}}\to0$ hầu chắc chắn nhưng $E Z_n=1$ và $E Z_n^2=n$. Biến mất từng điểm không kiểm soát giá trị lớn hiếm gặp.`);
const examA:E[]=[
 {title:b('Final A1 — conditioning and uniform integrability','Cuối kỳ A1 — điều kiện và khả tích đều'),skills:['proof','counterexample'],prompt:b(r`(a) For $X\in L^2$, $\mathcal G\subseteq\mathcal H$, prove $E[E[X\mid\mathcal H]\mid\mathcal G]=E[X\mid\mathcal G]$ from defining integrals, including uniqueness. (b) Derive the risk difference between the G and H predictors, explaining why it is nonnegative. (c) Construct a.s. convergence without convergence of expectations. Prove that a uniform $L^2$ bound repairs expectation convergence when $X_n\to X$ in probability.`,r`(a) Với $X\in L^2$, $\mathcal G\subseteq\mathcal H$, chứng minh $E[E[X\mid\mathcal H]\mid\mathcal G]=E[X\mid\mathcal G]$ từ tích phân định nghĩa, gồm tính duy nhất. (b) Dẫn xuất chênh lệch rủi ro giữa dự đoán theo G và H, giải thích không âm. (c) Dựng hội tụ hầu chắc chắn nhưng kỳ vọng không hội tụ. Chứng minh cận $L^2$ đồng đều sửa được hội tụ kỳ vọng khi $X_n\to X$ theo xác suất.`),hints:[b('Use test events in G; they are also in H.','Dùng biến cố thử trong G; chúng cũng thuộc H.'),b('Subtract the two conditional predictors and expand the square.','Lấy hiệu hai dự đoán có điều kiện rồi khai triển bình phương.')],solution:[b(r`For $A\in\mathcal G$, $E[1_AE[E[X\mid\mathcal H]\mid\mathcal G]]=E[1_AE[X\mid\mathcal H]]=E[1_AX]$. Measurability and integrability hold by the CE definition. If D is the difference of two versions, test separately on the G-measurable sets $\{D>1/k\}$ and $\{D<-1/k\}$ for every positive integer k. Each defining integral is zero while its signed magnitude is at least $P(A)/k$, forcing each set to be null. Their countable union contains $\{D\ne0\}$, proving equality a.s.`,r`Với $A\in\mathcal G$, $E[1_AE[E[X\mid\mathcal H]\mid\mathcal G]]=E[1_AE[X\mid\mathcal H]]=E[1_AX]$. Tính đo được và khả tích có từ định nghĩa CE. Nếu D là hiệu hai phiên bản, thử riêng trên tập đo được theo G $\{D>1/k\}$ và $\{D<-1/k\}$ với mọi số nguyên dương k. Mỗi tích phân định nghĩa bằng không trong khi độ lớn có dấu ít nhất $P(A)/k$, buộc mỗi tập có xác suất không. Hợp đếm được của chúng chứa $\{D\ne0\}$, chứng minh bằng nhau hầu chắc chắn.`),b(r`Write $m_G=E[X\mid G],m_H=E[X\mid H]$. The H-measurable difference $m_H-m_G$ is orthogonal to $X-m_H$ by conditional expectation (truncation justifies unbounded tests). Hence $E(X-m_G)^2-E(X-m_H)^2=E(m_H-m_G)^2\ge0$.`,r`Viết $m_G=E[X\mid G],m_H=E[X\mid H]$. Hiệu đo được theo H, $m_H-m_G$, trực giao với $X-m_H$ nhờ kỳ vọng có điều kiện (cắt cụt cho phép dùng hàm thử không bị chặn). Do đó $E(X-m_G)^2-E(X-m_H)^2=E(m_H-m_G)^2\ge0$.`),b(r`Take $X_n=n1_{U<1/n}$, X=0: a.s. convergence and EX_n=1. For the repair, a subsequence converges a.s. from convergence in probability; Fatou gives $EX^2\le\sup_nEX_n^2=C$. Then $E|X_n-X|^2\le4C$. Splitting $|X_n-X|$ at ε and using Cauchy–Schwarz gives $E|X_n-X|\le\epsilon+2\sqrt C\sqrt{P(|X_n-X|>\epsilon)}\to\epsilon$. Let ε→0; expectation convergence follows.`,r`Lấy $X_n=n1_{U<1/n}$, X=0: hội tụ hầu chắc chắn nhưng EX_n=1. Để sửa, hội tụ xác suất cho một dãy con hội tụ hầu chắc chắn; Fatou cho $EX^2\le\sup_nEX_n^2=C$. Khi đó $E|X_n-X|^2\le4C$. Tách $|X_n-X|$ tại ε, dùng Cauchy–Schwarz được $E|X_n-X|\le\epsilon+2\sqrt C\sqrt{P(|X_n-X|>\epsilon)}\to\epsilon$. Cho ε→0; suy ra hội tụ kỳ vọng.`)],criteria:[b('Correct nesting, defining identities and a.s. uniqueness; reversed nesting without justification is critical.','Đúng quan hệ lồng, đồng nhất thức định nghĩa và duy nhất hầu chắc chắn; đảo lồng thiếu căn cứ là lỗi nghiêm trọng.'),b('L2 orthogonality and nonnegative risk difference proved.','Chứng minh trực giao L2 và chênh rủi ro không âm.'),b('Valid counterexample and complete L2-to-L1 repair.','Phản ví dụ hợp lệ và sửa L2 sang L1 đầy đủ.')],errors:[b('DCT cannot be invoked without an integrable dominator; a bounded expectation is not UI.','Không dùng DCT khi chưa có hàm trội khả tích; kỳ vọng bị chặn không đồng nghĩa UI.')],repair:[35,36,37,38]},
 {title:b('Final A2 — ratio M-estimation under misspecification','Cuối kỳ A2 — M-estimator tỷ số dưới sai mô hình'),skills:['derivation','proof','transfer'],prompt:b(r`IID pairs $(W_i,Y_i)$ satisfy $W_i>0$, $E W_i=m>0$, $E W_i^2<\infty$, $E(W_iY_i)^2<\infty$. Define $\theta_0=E(WY)/m$ and the root $\hat\theta$ of $\sum_i W_i(Y_i-\theta)=0$. Derive consistency, the asymptotic distribution and a consistent sandwich variance estimate. State when variance is degenerate. Explain why replacing this variance by $\operatorname{Var}(Y)$ is generally false.`,r`Cặp IID $(W_i,Y_i)$ thỏa $W_i>0$, $E W_i=m>0$, $E W_i^2<\infty$, $E(W_iY_i)^2<\infty$. Đặt $\theta_0=E(WY)/m$ và nghiệm $\hat\theta$ của $\sum_i W_i(Y_i-\theta)=0$. Dẫn xuất nhất quán, phân phối tiệm cận và ước lượng phương sai sandwich nhất quán. Nêu khi phương sai suy biến. Giải thích vì sao thay bằng $\operatorname{Var}(Y)$ nói chung sai.`),hints:[b('Solve the estimating equation exactly before using Taylor.','Giải phương trình ước lượng chính xác trước khi dùng Taylor.'),b('The influence term is W(Y−theta), divided by EW.','Số hạng ảnh hưởng là W(Y−theta), chia cho EW.')],solution:[b(r`$\hat\theta=\overline{WY}/\bar W\to\theta_0$ by LLN and m>0. The identity $\sqrt n(\hat\theta-\theta_0)=\{n^{-1/2}\sum W_i(Y_i-\theta_0)\}/\bar W$ is exact. The summands have mean zero and finite variance B. CLT and Slutsky give $N(0,B/m^2)$.`,r`$\hat\theta=\overline{WY}/\bar W\to\theta_0$ nhờ LLN và m>0. Đồng nhất thức $\sqrt n(\hat\theta-\theta_0)=\{n^{-1/2}\sum W_i(Y_i-\theta_0)\}/\bar W$ là chính xác. Số hạng tổng có trung bình không, phương sai hữu hạn B. CLT và Slutsky cho $N(0,B/m^2)$.`),b(r`Use $\hat V=\{n^{-1}\sum W_i^2(Y_i-\hat\theta)^2\}/\bar W^2$. Expand around theta0; the cross average $n^{-1}\sum W_i^2(Y_i-\theta_0)$ is integrable by Cauchy–Schwarz, and $n^{-1}\sum W_i^2=O_p(1)$. LLN and consistency make the difference from B vanish, so $\hat V\to B/m^2$. Standard error is $\sqrt{\hat V/n}$.`,r`Dùng $\hat V=\{n^{-1}\sum W_i^2(Y_i-\hat\theta)^2\}/\bar W^2$. Khai triển quanh theta0; trung bình chéo $n^{-1}\sum W_i^2(Y_i-\theta_0)$ khả tích nhờ Cauchy–Schwarz, và $n^{-1}\sum W_i^2=O_p(1)$. LLN cùng nhất quán làm sai khác so với B biến mất, nên $\hat V\to B/m^2$. Sai số chuẩn là $\sqrt{\hat V/n}$.`),b(r`B=0 iff $W(Y-\theta_0)=0$ a.s.; with W>0 this means Y is constant a.s. If W is independent of Y with positive finite variance, $V=E(W^2)\operatorname{Var}(Y)/(EW)^2$, larger than Var(Y). A weighted mean does not inherit an unweighted standard error.`,r`B=0 khi và chỉ khi $W(Y-\theta_0)=0$ hầu chắc chắn; W>0 khiến Y là hằng số hầu chắc chắn. Nếu W độc lập Y và phương sai dương hữu hạn, $V=E(W^2)\operatorname{Var}(Y)/(EW)^2$, lớn hơn Var(Y). Trung bình có trọng số không kế thừa SE không trọng số.`)],criteria:[b('Correct target, exact expansion, moment assumptions and CLT use.','Đúng đại lượng đích, khai triển chính xác, giả thiết moment và CLT.'),b('Sandwich consistency justified including cross moments.','Giải thích nhất quán sandwich gồm moment chéo.'),b('Degeneracy and a valid unweighted-variance counterexample.','Suy biến và phản ví dụ phương sai không trọng số hợp lệ.')],errors:[b('Using model Fisher information without a specified correct likelihood is unjustified.','Dùng Fisher information mô hình khi chưa có likelihood đúng là không có căn cứ.')],repair:[48,49,50,51]},
 {title:b('Final A3 — constrained geometry and a convergence proof','Cuối kỳ A3 — hình học ràng buộc và chứng minh hội tụ'),skills:['proof','derivation'],prompt:b(r`Let $A\in\mathbb R^{m\times d}$ have full row rank, m<d. Derive the dual of $\min_x\frac12\|x\|^2$ subject to Ax=b, prove strong duality by constructing a primal-dual pair, and show uniqueness of x. For an arbitrary convex differentiable L-smooth function f with minimizer x*, prove $f(x_k)-f(x^*)\le L\|x_0-x^*\|^2/(2k)$ for gradient descent with step 1/L. Give a quadratic where step greater than 2/L diverges.`,r`Cho $A\in\mathbb R^{m\times d}$ hạng hàng đầy đủ, m<d. Dẫn xuất đối ngẫu của $\min_x\frac12\|x\|^2$ với Ax=b, chứng minh đối ngẫu mạnh bằng dựng cặp primal-dual và chứng minh x duy nhất. Với f lồi khả vi L-trơn bất kỳ có cực tiểu x*, chứng minh $f(x_k)-f(x^*)\le L\|x_0-x^*\|^2/(2k)$ cho gradient descent bước 1/L. Cho hàm toàn phương phân kỳ khi bước lớn hơn 2/L.`),hints:[b('Use L(x,λ)=||x||²/2+λᵀ(b−Ax).','Dùng L(x,λ)=||x||²/2+λᵀ(b−Ax).'),b('Combine convexity at x_k with descent at x_{k+1}; then telescope squared distances.','Kết hợp tính lồi tại x_k với giảm hàm tại x_{k+1}; rồi cộng rút gọn khoảng cách bình phương.')],solution:[b(r`Infimizing gives $x=A^T\lambda$, $g(\lambda)=\lambda^Tb-\|A^T\lambda\|^2/2$. Since $AA^T\succ0$, solve $AA^T\lambda^*=b$ and set $x^*=A^T\lambda^*$. Feasibility and equality of objective values prove zero gap. Every feasible $x=x^*+z$ has Az=0, so $\langle x^*,z\rangle=0$; its objective is the optimum plus $\|z\|^2/2$.`,r`Lấy inf cho $x=A^T\lambda$, $g(\lambda)=\lambda^Tb-\|A^T\lambda\|^2/2$. Vì $AA^T\succ0$, giải $AA^T\lambda^*=b$, đặt $x^*=A^T\lambda^*$. Khả thi và bằng nhau của giá trị mục tiêu chứng minh gap không. Mọi $x=x^*+z$ khả thi có Az=0 nên $\langle x^*,z\rangle=0$; mục tiêu bằng tối ưu cộng $\|z\|^2/2$.`),b(r`Write $g_k=\nabla f(x_k)$. Smoothness gives $f(x_{k+1})\le f(x_k)-\|g_k\|^2/(2L)$; convexity gives $f(x_k)-f^*\le\langle g_k,x_k-x^*\rangle$. Combining yields $f(x_{k+1})-f^*\le\frac L2(\|x_k-x^*\|^2-\|x_{k+1}-x^*\|^2)$. Sum k terms and use monotone objective values to bound k times the final gap.`,r`Viết $g_k=\nabla f(x_k)$. Tính trơn cho $f(x_{k+1})\le f(x_k)-\|g_k\|^2/(2L)$; tính lồi cho $f(x_k)-f^*\le\langle g_k,x_k-x^*\rangle$. Kết hợp được $f(x_{k+1})-f^*\le\frac L2(\|x_k-x^*\|^2-\|x_{k+1}-x^*\|^2)$. Cộng k số hạng và dùng giá trị mục tiêu giảm để chặn k lần gap cuối.`),b(r`For $f(x)=Lx^2/2$, $x_{k+1}=(1-\eta L)x_k$. If η>2/L and x0≠0, the magnitude grows geometrically; at η=2/L it oscillates without decay. The theorem's safe step and the boundary are different claims.`,r`Với $f(x)=Lx^2/2$, $x_{k+1}=(1-\eta L)x_k$. Nếu η>2/L và x0≠0 thì độ lớn tăng hình học; tại η=2/L dao động không giảm. Bước an toàn của định lý và trường hợp biên là hai kết luận khác nhau.`)],criteria:[b('Correct dual sign, feasibility, zero gap and rank assumption.','Đúng dấu đối ngẫu, khả thi, gap không và giả thiết hạng.'),b('Complete distance telescoping proof with constants.','Chứng minh cộng rút gọn khoảng cách đầy đủ đúng hằng số.'),b('Valid divergence and boundary counterexamples.','Phản ví dụ phân kỳ và biên hợp lệ.')],errors:[b('A gradient norm tending to zero alone does not prove the stated rate.','Chỉ gradient tiến về không không chứng minh tốc độ đã nêu.')],repair:[64,65,66,69]},
 {title:b('Final A4 — overlap and matrix sequential inference','Cuối kỳ A4 — nhãn chồng lấn và suy luận tuần tự ma trận'),skills:['proof','derivation','counterexample'],prompt:b(r`Let $D_t=h^{-1}\sum_{j=0}^{h-1}\epsilon_{t-j}$ for IID zero-mean variance-$\sigma^2$ innovations and fixed h≥2. Derive every autocovariance, the long-run variance and the asymptotic variance inflation relative to IID. Derive the matrix Kalman measurement update for an independent Gaussian prior/error model. Explain why using a smoothed state at forecast time can invalidate an otherwise correct covariance calculation.`,r`Cho $D_t=h^{-1}\sum_{j=0}^{h-1}\epsilon_{t-j}$ với innovation IID trung bình không phương sai $\sigma^2$, h≥2 cố định. Dẫn xuất mọi hiệp phương sai, phương sai dài hạn và hệ số phóng đại tiệm cận so với IID. Dẫn xuất cập nhật quan sát Kalman ma trận với tiên nghiệm/nhiễu Gaussian độc lập. Giải thích vì sao dùng trạng thái đã smoothing tại thời điểm dự báo có thể làm sai một phép tính hiệp phương sai vốn đúng.`),hints:[b('Count shared innovations in two windows.','Đếm innovation chung trong hai cửa sổ.'),b('Regress the state error on the innovation and prove the residual is independent.','Hồi quy sai số trạng thái lên innovation rồi chứng minh phần dư độc lập.')],solution:[b(r`For |k|<h there are h−|k| common terms, so $\gamma_k=\sigma^2(h-|k|)/h^2$; otherwise zero. Thus $\gamma_0=\sigma^2/h$ and $\Omega=\gamma_0+2\sum_{k=1}^{h-1}\gamma_k=\sigma^2$. The variance inflation is h and the SE inflation $\sqrt h$. Finite-n variance retains the weights 1−k/n.`,r`Khi |k|<h có h−|k| số hạng chung nên $\gamma_k=\sigma^2(h-|k|)/h^2$; ngoài ra bằng không. Vì thế $\gamma_0=\sigma^2/h$, $\Omega=\gamma_0+2\sum_{k=1}^{h-1}\gamma_k=\sigma^2$. Hệ số phương sai là h, hệ số SE là $\sqrt h$. Phương sai hữu hạn vẫn giữ trọng số 1−k/n.`),b(r`For $x\sim N(a,P)$, $y=Hx+v$, $v\sim N(0,R)$ independent and R≻0, set $S=HPH^T+R$, $K=PH^TS^{-1}$. Residual $x-a-K(y-Ha)$ has zero covariance with y and is jointly Gaussian, hence independent. Conditional mean is $a+K(y-Ha)$, covariance $P-PH^TS^{-1}HP$.`,r`Với $x\sim N(a,P)$, $y=Hx+v$, $v\sim N(0,R)$ độc lập và R≻0, đặt $S=HPH^T+R$, $K=PH^TS^{-1}$. Phần dư $x-a-K(y-Ha)$ có hiệp phương sai không với y và đồng Gaussian nên độc lập. Trung bình có điều kiện là $a+K(y-Ha)$, hiệp phương sai $P-PH^TS^{-1}HP$.`),b(r`Filtering uses $\mathcal F_t$, smoothing uses $\mathcal F_T$ with T>t. The latter can depend on the target itself and is not generally $\mathcal F_t$-measurable. Correct Gaussian conditioning on the wrong information set is still an invalid forecast experiment.`,r`Filtering dùng $\mathcal F_t$, smoothing dùng $\mathcal F_T$ với T>t. Cách sau có thể phụ thuộc chính nhãn và nói chung không đo được theo $\mathcal F_t$. Lấy điều kiện Gaussian đúng nhưng trên tập thông tin sai vẫn là thí nghiệm dự báo không hợp lệ.`)],criteria:[b('Correct overlap count, long-run variance and dependence handling.','Đúng đếm chồng lấn, phương sai dài hạn và xử lý phụ thuộc.'),b('Matrix update derived with Gaussianity, independence and dimensions.','Dẫn xuất cập nhật ma trận có Gaussian, độc lập và kích thước.'),b('No future-information leakage; distinguishes filter/smoother.','Không rò thông tin tương lai; phân biệt filter/smoother.')],errors:[b('IID variance for overlapping labels and future smoothing are critical errors.','Phương sai IID cho nhãn chồng lấn và smoothing tương lai là lỗi nghiêm trọng.')],repair:[73,77,79,80,81]},
 {title:b('Final A review — audit an invalid proof','Đối chiếu A — audit chứng minh sai'),skills:['proof','counterexample','transfer'],prompt:b(r`A submitted argument says: “$X_n\to X$ a.s., so expectations converge; our loss sequence is stationary, so its average is asymptotically Gaussian; KKT stationarity holds, so the feasible point is globally optimal.” Give one explicit counterexample per implication and a sufficient repair for each.`,r`Một bài làm viết: “$X_n\to X$ hầu chắc chắn nên kỳ vọng hội tụ; chuỗi loss dừng nên trung bình tiệm cận Gaussian; thỏa tính dừng KKT nên điểm khả thi tối ưu toàn cục.” Cho một phản ví dụ tường minh cho mỗi suy luận và điều kiện đủ sửa từng lỗi.`),hints:[b('Use rare spikes, a common random variable, and a nonconvex objective.','Dùng đỉnh hiếm, biến ngẫu nhiên chung và mục tiêu không lồi.')],solution:[b(r`The spike $n1_{U<1/n}$ has expectations 1 but limit 0. An integrable dominator or UI plus convergence in probability repairs expectation interchange.`,r`Đỉnh $n1_{U<1/n}$ có kỳ vọng 1 nhưng giới hạn 0. Hàm trội khả tích hoặc UI cộng hội tụ xác suất sửa việc đổi kỳ vọng.`),b(r`$D_t=Z$ with non-Gaussian Z is stationary and $\bar D_n=Z$; no shrinking uncertainty occurs. A selected dependent CLT requires additional dependence/moment assumptions, such as a finite-dependent sequence with finite variance and positive long-run variance.`,r`$D_t=Z$ với Z không Gaussian là dừng, $\bar D_n=Z$; bất định không co lại. CLT phụ thuộc được chọn cần giả thiết phụ thuộc/moment thêm, chẳng hạn chuỗi phụ thuộc hữu hạn có phương sai hữu hạn và phương sai dài hạn dương.`),b(r`For $f(x)=(x^2-1)^2$, x=0 is stationary but f(0)=1>f(±1)=0. Convex objective and convex inequalities/affine equalities plus full feasible KKT conditions give sufficiency; stationarity alone is incomplete.`,r`Với $f(x)=(x^2-1)^2$, x=0 dừng nhưng f(0)=1>f(±1)=0. Mục tiêu lồi và bất đẳng thức lồi/đẳng thức affine cùng đủ điều kiện KKT khả thi cho tính đủ; riêng tính dừng chưa đủ.`)],criteria:[b('Three mathematically valid counterexamples.','Ba phản ví dụ toán học hợp lệ.'),b('Each repair targets the missing hypothesis.','Mỗi cách sửa nhắm đúng giả thiết thiếu.'),b('Does not convert one sufficient condition into a necessary claim.','Không biến một điều kiện đủ thành kết luận cần.')],errors:[b('A counterexample must meet the original premises, not merely fail the conclusion.','Phản ví dụ phải thỏa tiền đề gốc, không chỉ làm kết luận sai.')],repair:[32,38,64,76]},
];
add(99,b('Final comprehensive assessment — form A','Đánh giá toán tổng hợp — đề A'),[44,60,72,84,98],finalDefinition,finalStatement,finalProof,finalExample,finalFailure,examA,'a-prob','Lectures 16–19 and 25–26; original four-part examination','assessment');

function repairWeek(week:number,origin:number,title:B,items:E[],prerequisites:number[]){
 const recalled=items.map(e=>({...e,title:b(`Reconstruction: ${e.title.en}`,`Tái dựng: ${e.title.vi}`),prompt:b(`Scheduled remediation of W${origin}; this is a repeat, not an unseen test. Cover the original solution and rebuild the argument, then identify the first incorrect implication in your previous attempt. If already correct, derive the result by a second route and document which hypothesis cannot be dropped.\n\n${e.prompt.en}`,`Buổi sửa lỗi W${origin} đã có trong lịch; đây là bài làm lại, không phải đề chưa gặp. Che lời giải cũ, tự dựng lại lập luận rồi xác định suy luận sai đầu tiên ở lần trước. Nếu đã đúng, dẫn xuất bằng cách thứ hai và ghi giả thiết không thể bỏ.\n\n${e.prompt.vi}`)}));
 add(week,title,prerequisites,finalDefinition,finalStatement,finalProof,finalExample,finalFailure,recalled,'a-prob','Lectures 16–19; scheduled reconstruction of original assessment','remediation');
 weeks.at(-1)!.exercises.forEach((e,i)=>e.practiceOrigin=`m2-w${String(origin).padStart(3,'0')}-e${i+1}`);
}
repairWeek(100,99,b('Final A repair: assumptions before retesting','Sửa đề A: củng cố giả thiết trước thi lại'),examA,[99]);

const examB:E[]=[
 {title:b('Final B1 — stopping and failure of uniform integrability','Cuối kỳ B1 — dừng và mất khả tích đều'),skills:['proof','counterexample','transfer'],prompt:b(r`Let independent fair coins be observed, T the first head, and $M_n=1$ if T≤n, otherwise $M_n=-(2^n-1)$, with M0=0. Prove M is a martingale, T is finite a.s., $EM_n=0$ and $EM_T=1$. Prove optional stopping for an arbitrary bounded stopping time of an integrable discrete martingale. Identify precisely why that proof does not extend here; establish non-UI of M_n.`,r`Quan sát đồng xu công bằng độc lập, T là lần ngửa đầu, $M_n=1$ nếu T≤n, nếu chưa thì $M_n=-(2^n-1)$, M0=0. Chứng minh M là martingale, T hữu hạn hầu chắc chắn, $EM_n=0$ và $EM_T=1$. Chứng minh dừng tùy chọn cho thời điểm dừng bị chặn bất kỳ của martingale rời rạc khả tích. Chỉ đúng bước không mở rộng được ở đây; chứng minh M_n không UI.`),hints:[b('On survival to n, average the two possible next wealths.','Khi sống tới n, lấy trung bình hai mức tài sản kế tiếp.'),b('For a bounded time write the stopped sum using indicators {T≥k}.','Với thời gian bị chặn, viết tổng đã dừng bằng chỉ báo {T≥k}.')],solution:[b(r`On T≤n the value stays 1. On T>n, the next conditional mean is $[1-(2^{n+1}-1)]/2=-(2^n-1)$. Thus M is an integrable martingale. $P(T>n)=2^{-n}\to0$, and $EM_n=(1-2^{-n})-2^{-n}(2^n-1)=0$, while M_T=1 a.s.`,r`Trên T≤n, giá trị giữ 1. Trên T>n, trung bình có điều kiện bước sau là $[1-(2^{n+1}-1)]/2=-(2^n-1)$. Vì thế M là martingale khả tích. $P(T>n)=2^{-n}\to0$, $EM_n=(1-2^{-n})-2^{-n}(2^n-1)=0$, còn M_T=1 hầu chắc chắn.`),b(r`For stopping time S≤N, $M_S=M_0+\sum_{k=1}^N1_{\{S\ge k\}}(M_k-M_{k-1})$. The indicator is $\mathcal F_{k-1}$-measurable and bounded, so each increment term has expectation zero. Hence $EM_S=EM_0$. This establishes the bounded theorem from the martingale identity.`,r`Với thời điểm dừng S≤N, $M_S=M_0+\sum_{k=1}^N1_{\{S\ge k\}}(M_k-M_{k-1})$. Chỉ báo đo được theo $\mathcal F_{k-1}$, bị chặn, nên mỗi số hạng gia số có kỳ vọng không. Do đó $EM_S=EM_0$. Đây là chứng minh định lý bị chặn từ đồng nhất thức martingale.`),b(r`The bounded theorem gives $EM_{T\wedge n}=0$. Passing to T requires justified expectation convergence, not merely T<∞ a.s. Given cutoff K choose n with 2^n−1>K; then $E[|M_n|1_{|M_n|>K}]\ge1-2^{-n}$, so the uniform tail does not vanish. Non-UI prevents the unjustified limit.`,r`Định lý bị chặn cho $EM_{T\wedge n}=0$. Chuyển sang T cần hội tụ kỳ vọng có căn cứ, không chỉ T<∞ hầu chắc chắn. Với ngưỡng K chọn n có 2^n−1>K; khi đó $E[|M_n|1_{|M_n|>K}]\ge1-2^{-n}$, nên đuôi đồng đều không biến mất. Mất UI ngăn phép chuyển giới hạn thiếu căn cứ.`)],criteria:[b('Martingale and stopping-time measurability verified correctly.','Kiểm tra đúng martingale và tính đo được thời điểm dừng.'),b('Bounded optional-stopping proof complete.','Chứng minh dừng bị chặn đầy đủ.'),b('Explicit non-UI tail calculation and invalid-limit diagnosis.','Tính đuôi không UI tường minh và chẩn đoán giới hạn sai.')],errors:[b('Finite expected T alone is not enough here: increments are not uniformly bounded.','Chỉ ET hữu hạn chưa đủ ở đây: gia số không bị chặn đồng đều.')],repair:[35,38,43,44]},
 {title:b('Final B2 — nonregular support and a quasi-likelihood','Cuối kỳ B2 — support không chính quy và quasi-likelihood'),skills:['derivation','proof','counterexample'],prompt:b(r`(a) For IID U(0,θ), θ>0, derive the MLE and the limit distribution of $n(\theta-\hat\theta)/\theta$ directly from its CDF. Identify the failed regularity and why a root-n Fisher interval is wrong. (b) For IID nonnegative Y with EY=μ>0 and variance σ² finite, maximize the Poisson criterion $Y\eta-e^\eta$ even when Y is not Poisson. Derive consistency and asymptotic variance for η=log μ; compare the naive Poisson information.`,r`(a) Với IID U(0,θ), θ>0, dẫn xuất MLE và phân phối giới hạn của $n(\theta-\hat\theta)/\theta$ trực tiếp từ CDF. Chỉ ra điều kiện chính quy hỏng và vì sao khoảng Fisher căn-n sai. (b) Với Y IID không âm, EY=μ>0, phương sai σ² hữu hạn, cực đại tiêu chuẩn Poisson $Y\eta-e^\eta$ kể cả khi Y không Poisson. Dẫn xuất nhất quán và phương sai tiệm cận cho η=log μ; so với information Poisson ngây thơ.`),hints:[b('For the endpoint model, the maximum order statistic determines the likelihood constraint.','Ở mô hình đầu mút, thống kê cực đại quyết định ràng buộc likelihood.'),b('For quasi-likelihood, solve exp(eta)=sample mean.','Với quasi-likelihood, giải exp(eta)=trung bình mẫu.')],solution:[b(r`Likelihood is θ^{-n}1_{θ≥Y_(n)}, so $\hat\theta=Y_{(n)}$. For z≥0 and n>z, $P(n(\theta-\hat\theta)/\theta>z)=(1-z/n)^n\to e^{-z}$. Thus the limit is Exp(1); the error has order n^{-1}, not n^{-1/2}. Parameter-dependent support invalidates the usual score differentiation under the integral.`,r`Likelihood là θ^{-n}1_{θ≥Y_(n)}, nên $\hat\theta=Y_{(n)}$. Với z≥0 và n>z, $P(n(\theta-\hat\theta)/\theta>z)=(1-z/n)^n\to e^{-z}$. Giới hạn là Exp(1); sai số bậc n^{-1}, không phải n^{-1/2}. Support phụ thuộc tham số làm hỏng phép đổi đạo hàm score dưới tích phân thông thường.`),b(r`When $\bar Y>0$, strict concavity gives $\hat\eta=\log\bar Y$. LLN implies $\bar Y\to\mu>0$, so the event of a finite maximizer has probability tending to one and $\hat\eta\to\log\mu$. Delta method gives $\sqrt n(\hat\eta-\log\mu)\Rightarrow N(0,\sigma^2/\mu^2)$.`,r`Khi $\bar Y>0$, lõm chặt cho $\hat\eta=\log\bar Y$. LLN cho $\bar Y\to\mu>0$, nên xác suất có cực đại hữu hạn tiến tới một, $\hat\eta\to\log\mu$. Delta method cho $\sqrt n(\hat\eta-\log\mu)\Rightarrow N(0,\sigma^2/\mu^2)$.`),b(r`Poisson information per observation is μ, so the model variance would be 1/μ. It agrees only when σ²=μ. For Y=2B, B~Bernoulli(1/2), μ=1 and σ²=1 happen to agree; choose instead Y=3B to obtain μ=3/2, σ²=9/4, true asymptotic variance 1 versus naive 2/3. Moment equality, not the criterion's name, determines the sandwich.`,r`Information Poisson mỗi quan sát là μ, nên phương sai mô hình là 1/μ. Chúng chỉ trùng khi σ²=μ. Với Y=2B, B~Bernoulli(1/2), μ=1 và σ²=1 tình cờ trùng; chọn Y=3B được μ=3/2, σ²=9/4, phương sai tiệm cận thật 1, ngây thơ 2/3. Đẳng thức moment, không phải tên tiêu chuẩn, quyết định sandwich.`)],criteria:[b('Correct support-aware likelihood and non-Gaussian endpoint limit.','Likelihood đúng support và giới hạn đầu mút không Gaussian.'),b('Quasi-estimator, consistency and finite-maximizer qualification.','Ước lượng quasi, nhất quán và điều kiện cực đại hữu hạn.'),b('Sandwich variance and an explicit misspecification example.','Phương sai sandwich và ví dụ sai mô hình tường minh.')],errors:[b('Differentiating the density while ignoring its support loses a boundary term.','Đạo hàm mật độ mà bỏ support làm mất số hạng biên.')],repair:[48,50,51,59]},
 {title:b('Final B3 — online projection versus statistical generalization','Cuối kỳ B3 — phép chiếu online và tổng quát hóa thống kê'),skills:['proof','derivation','transfer'],prompt:b(r`Let K be closed convex of diameter D, convex losses f_t and subgradients ||g_t||≤G. Prove projected OGD regret at constant η is at most $D^2/(2\eta)+\eta G^2T/2$ against any fixed u∈K, choosing η. Then for N fixed hypotheses with IID [0,1] losses, prove a probability-1−δ ERM excess-risk bound from Hoeffding plus a union bound. Explain why OGD regret alone is not a test-set IID guarantee on financial time series.`,r`Cho K đóng lồi đường kính D, loss f_t lồi, dưới gradient ||g_t||≤G. Chứng minh regret OGD có chiếu với η cố định không quá $D^2/(2\eta)+\eta G^2T/2$ so với mọi u∈K cố định, rồi chọn η. Với N giả thuyết cố định có loss IID trong [0,1], chứng minh cận excess risk ERM xác suất 1−δ từ Hoeffding và union bound. Giải thích vì sao regret OGD tự nó không là bảo đảm tập test IID cho time series tài chính.`),hints:[b('Projection decreases distance to any comparator in K.','Phép chiếu giảm khoảng cách tới mọi đối chứng trong K.'),b('Excess risk is bounded by two uniform deviations.','Excess risk bị chặn bởi hai sai lệch đồng đều.')],solution:[b(r`Projection gives $\|x_{t+1}-u\|^2\le\|x_t-\eta g_t-u\|^2$. Rearranging and convexity yield $f_t(x_t)-f_t(u)\le(\|x_t-u\|^2-\|x_{t+1}-u\|^2)/(2\eta)+\eta G^2/2$. Sum and discard the final nonnegative distance. For D,G>0 choose η=D/(G√T), giving DG√T; D=0 or G=0 has zero regret and needs no division.`,r`Phép chiếu cho $\|x_{t+1}-u\|^2\le\|x_t-\eta g_t-u\|^2$. Sắp xếp và dùng tính lồi được $f_t(x_t)-f_t(u)\le(\|x_t-u\|^2-\|x_{t+1}-u\|^2)/(2\eta)+\eta G^2/2$. Cộng rồi bỏ khoảng cách cuối không âm. Khi D,G>0 chọn η=D/(G√T), được DG√T; D=0 hoặc G=0 có regret không, không cần chia.`),b(r`For fixed h, Hoeffding gives $P(|\hat R(h)-R(h)|>\epsilon)\le2e^{-2n\epsilon^2}$. Union over N gives ε=√(log(2N/δ)/(2n)). On that event, $R(\hat h)-R(h^*)\le[R-\hat R](\hat h)+[\hat R(\hat h)-\hat R(h^*)]+[\hat R-R](h^*)\le2\epsilon$.`,r`Với h cố định, Hoeffding cho $P(|\hat R(h)-R(h)|>\epsilon)\le2e^{-2n\epsilon^2}$. Union bound trên N cho ε=√(log(2N/δ)/(2n)). Trên biến cố ấy, $R(\hat h)-R(h^*)\le[R-\hat R](\hat h)+[\hat R(\hat h)-\hat R(h^*)]+[\hat R-R](h^*)\le2\epsilon$.`),b('OGD is a pathwise comparison to one fixed comparator on the observed sequence; it allows changing losses. The ERM claim requires a fixed finite class and IID sampling. To claim generalization under dependence one must replace the concentration assumption; neither theorem proves profitable execution.','OGD so sánh theo từng chuỗi quan sát với một đối chứng cố định; loss có thể thay đổi. ERM đòi lớp hữu hạn cố định và lấy mẫu IID. Muốn kết luận tổng quát hóa dưới phụ thuộc phải thay giả thiết tập trung; không định lý nào chứng minh thực thi có lời.')],criteria:[b('Correct projection/telescoping constants and comparator class.','Đúng hằng số chiếu/cộng rút gọn và lớp đối chứng.'),b('Union bound and 2ε ERM decomposition complete.','Union bound và phân rã ERM 2ε đầy đủ.'),b('Separates pathwise regret from sampling-based generalization.','Tách regret theo chuỗi khỏi tổng quát hóa dựa trên lấy mẫu.')],errors:[b('Replacing the fixed comparator with the best action each day changes the theorem.','Thay đối chứng cố định bằng hành động tốt nhất mỗi ngày làm đổi định lý.')],repair:[66,85,86,90]},
 {title:b('Final B4 — projection smoothing and dependent estimation','Cuối kỳ B4 — smoothing bằng phép chiếu và ước lượng phụ thuộc'),skills:['derivation','proof','counterexample'],prompt:b(r`In a correctly specified Gaussian state model, given $\mathcal F_t$, let x_t have mean m and covariance P, and $x_{t+1}=Ax_t+w$ with independent covariance Q and $P^-=APA^T+Q\succ0$. Derive $E[x_t\mid x_{t+1},\mathcal F_t]$ and the RTS smoother recursion using tower expectation. Separately, show that $D_t=Z+\epsilon_t$ with independent centered Z and IID centered ε is stationary but its sample mean need not consistently estimate zero. Identify the missing condition in a stationary-CLT argument.`,r`Trong mô hình trạng thái Gaussian đúng, cho $\mathcal F_t$, x_t có trung bình m, hiệp phương sai P, $x_{t+1}=Ax_t+w$ với nhiễu độc lập hiệp phương sai Q, $P^-=APA^T+Q\succ0$. Dẫn xuất $E[x_t\mid x_{t+1},\mathcal F_t]$ và truy hồi smoother RTS bằng kỳ vọng lồng. Riêng, chứng minh $D_t=Z+\epsilon_t$ với Z trung tâm độc lập và ε IID trung tâm là dừng nhưng trung bình mẫu không nhất thiết ước lượng nhất quán không. Chỉ giả thiết thiếu khi suy luận CLT từ tính dừng.`),hints:[b('The conditional cross covariance is PAᵀ.','Hiệp phương sai chéo có điều kiện là PAᵀ.'),b('The common component survives averaging.','Thành phần chung không mất khi lấy trung bình.')],solution:[b(r`Joint Gaussian conditioning gives $J=PA^T(P^-)^{-1}$ and $E[x_t\mid x_{t+1},\mathcal F_t]=m+J(x_{t+1}-Am)$. Its residual covariance is $P-JP^-J^T$.`,r`Lấy điều kiện đồng Gaussian cho $J=PA^T(P^-)^{-1}$ và $E[x_t\mid x_{t+1},\mathcal F_t]=m+J(x_{t+1}-Am)$. Hiệp phương sai phần dư là $P-JP^-J^T$.`),b(r`The Markov state/independent-noise model makes future observations conditionally irrelevant for x_t once x_{t+1} and F_t are known. Tower and total covariance give $m_{t|T}=m+J(m_{t+1|T}-Am)$ and $P_{t|T}=P+J(P_{t+1|T}-P^-)J^T$. The conditional irrelevance is a model assumption, not a generic tower identity.`,r`Mô hình trạng thái Markov/nhiễu độc lập làm quan sát tương lai không thêm thông tin về x_t khi đã biết x_{t+1} và F_t. Kỳ vọng lồng và hiệp phương sai toàn phần cho $m_{t|T}=m+J(m_{t+1|T}-Am)$, $P_{t|T}=P+J(P_{t+1|T}-P^-)J^T$. Tính không thêm thông tin là giả thiết mô hình, không phải đồng nhất thức tower tổng quát.`),b(r`With Var(Z)>0 and finite variances, D is stationary, $\bar D_n=Z+\bar\epsilon_n\to Z$ a.s. by SLLN, not zero in probability. For h≠0, γ_h=Var(Z), so absolute covariance summability fails; the common component also makes the sequence nonergodic. Stationarity alone supplies neither LLN nor CLT.`,r`Với Var(Z)>0 và phương sai hữu hạn, D dừng, $\bar D_n=Z+\bar\epsilon_n\to Z$ hầu chắc chắn theo SLLN, không tới không theo xác suất. Khi h≠0, γ_h=Var(Z), nên không khả tổng tuyệt đối; thành phần chung còn làm chuỗi không ergodic. Tính dừng tự nó không cho LLN hay CLT.`)],criteria:[b('Correct conditional covariance/gain and Gaussian assumptions.','Đúng gain/hiệp phương sai có điều kiện và giả thiết Gaussian.'),b('RTS mean/covariance derived using Markov structure.','Dẫn xuất trung bình/hiệp phương sai RTS bằng cấu trúc Markov.'),b('Valid stationary nonergodic counterexample and failed inference.','Phản ví dụ dừng không ergodic hợp lệ và suy luận thất bại.')],errors:[b('RTS covariance is not obtained by merely replacing the filtered mean.','Không thể lấy hiệp phương sai RTS bằng cách chỉ thay trung bình filtered.')],repair:[36,73,76,81]},
 {title:b('Final B review — justify the theorem you invoked','Đối chiếu B — biện minh định lý đã dùng'),skills:['proof','transfer','counterexample'],prompt:b(r`Prove that projection onto a nonempty closed convex subset K of finite-dimensional Euclidean space exists uniquely and satisfies $\|\Pi_K(z)-u\|\le\|z-u\|$ for every u∈K. Give a closed nonconvex K for which uniqueness fails. This checks a lemma used in B3, not keyword recall.`,r`Chứng minh phép chiếu lên tập K không rỗng đóng lồi trong không gian Euclid hữu hạn chiều tồn tại duy nhất, thỏa $\|\Pi_K(z)-u\|\le\|z-u\|$ cho mọi u∈K. Cho K đóng không lồi khiến duy nhất sai. Bài này kiểm tra bổ đề dùng ở B3, không phải nhớ từ khóa.`),hints:[b('Restrict minimization to a sufficiently large closed ball.','Giới hạn cực tiểu hóa trong một quả cầu đóng đủ lớn.'),b('Differentiate along a feasible segment starting at the projection.','Lấy đạo hàm dọc đoạn khả thi bắt đầu ở điểm chiếu.')],solution:[b(r`Choose u0∈K. Points farther from z than ||z−u0||+1 cannot minimize; restricting to the resulting closed bounded subset makes it compact. Continuous squared distance attains a minimum. Strict convexity of squared norm and convexity of K make the minimizer p unique.`,r`Chọn u0∈K. Điểm xa z hơn ||z−u0||+1 không thể cực tiểu; giới hạn vào tập đóng bị chặn ấy cho tập compact. Bình phương khoảng cách liên tục đạt cực tiểu. Lồi chặt của chuẩn bình phương và tính lồi K làm điểm cực tiểu p duy nhất.`),b(r`For u∈K, p+s(u−p)∈K for 0≤s≤1. The one-sided derivative of squared distance at s=0 yields $\langle z-p,u-p\rangle\le0$. Expand $\|z-u\|^2=\|z-p\|^2+\|p-u\|^2+2\langle z-p,p-u\rangle\ge\|p-u\|^2$.`,r`Với u∈K, p+s(u−p)∈K khi 0≤s≤1. Đạo hàm một phía của khoảng cách bình phương tại s=0 cho $\langle z-p,u-p\rangle\le0$. Khai triển $\|z-u\|^2=\|z-p\|^2+\|p-u\|^2+2\langle z-p,p-u\rangle\ge\|p-u\|^2$.`),b(r`K={−1,1} is closed but nonconvex; z=0 has two equally near minimizers. On an open interval the infimum can also fail to be attained, showing why closedness mattered.`,r`K={−1,1} đóng nhưng không lồi; z=0 có hai điểm cực tiểu cách đều. Trên khoảng mở, infimum cũng có thể không đạt, cho thấy vai trò đóng.`)],criteria:[b('Attainment and uniqueness proved with correct hypotheses.','Chứng minh đạt cực tiểu và duy nhất đúng giả thiết.'),b('Variational inequality and distance bound derived.','Dẫn xuất bất đẳng thức biến phân và cận khoảng cách.'),b('Valid nonconvex counterexample and closedness boundary.','Phản ví dụ không lồi và giới hạn tính đóng hợp lệ.')],errors:[b('A closed set need not be compact unless bounded in finite dimension.','Tập đóng chưa chắc compact nếu không bị chặn trong hữu hạn chiều.')],repair:[5,11,61,68]},
];
add(101,b('Final comprehensive assessment — form B','Đánh giá toán tổng hợp — đề B'),[99,100],finalDefinition,finalStatement,finalProof,finalExample,finalFailure,examB,'a-prob','Lectures 19, 25–26; original transfer form, not a numerical variant','assessment');
repairWeek(103,101,b('Final B repair and dependency closure','Sửa đề B và các prerequisite liên quan'),examB,[101,102]);

const capstone:E[]=[
 {title:b('Prove the Joseph covariance identity','Chứng minh đồng nhất thức hiệp phương sai Joseph'),skills:['proof','numerical analysis'],prompt:b(r`For P≽0, R≻0, S=HPHᵀ+R and K=PHᵀS⁻¹, prove $(I-KH)P(I-KH)^T+KRK^T=P-KSK^T$. Show why the left side remains PSD for any gain K, even a nonoptimal one. Explain the floating-point advantage and its limit.`,r`Với P≽0, R≻0, S=HPHᵀ+R và K=PHᵀS⁻¹, chứng minh $(I-KH)P(I-KH)^T+KRK^T=P-KSK^T$. Chứng minh vế trái vẫn PSD với mọi gain K, kể cả không tối ưu. Giải thích ưu điểm dấu phẩy động và giới hạn của nó.`),hints:[b('Expand and group the two noise terms into KSKᵀ.','Khai triển và nhóm hai số hạng nhiễu thành KSKᵀ.')],solution:[b(r`Expansion gives $P-KHP-PH^TK^T+K(HPH^T+R)K^T$. With the optimal K, $KS=PH^T$ and $SK^T=HP$, so both cross terms equal KSKᵀ; the result is P−KSKᵀ.`,r`Khai triển cho $P-KHP-PH^TK^T+K(HPH^T+R)K^T$. Với K tối ưu, $KS=PH^T$, $SK^T=HP$, nên cả hai số hạng chéo đều bằng KSKᵀ; kết quả là P−KSKᵀ.`),b(r`For arbitrary K and vector z, the left quadratic form equals $\|P^{1/2}(I-KH)^Tz\|^2+\|R^{1/2}K^Tz\|^2\ge0$. It is the covariance of the updated error when state error and measurement noise are independent.`,r`Với K bất kỳ và vector z, dạng toàn phương vế trái bằng $\|P^{1/2}(I-KH)^Tz\|^2+\|R^{1/2}K^Tz\|^2\ge0$. Đó là hiệp phương sai sai số cập nhật khi sai số trạng thái độc lập nhiễu quan sát.`),b('The additive form avoids cancellation between nearly equal covariance matrices, but floating-point roundoff still needs symmetry/PSD tolerances and stable solves. It cannot repair a wrong noise model or an incorrectly timed observation.','Dạng cộng tránh triệt tiêu giữa hai ma trận hiệp phương sai gần bằng, nhưng sai số làm tròn vẫn cần dung sai đối xứng/PSD và phép giải ổn định. Nó không sửa được mô hình nhiễu sai hoặc quan sát dùng sai thời điểm.')],criteria:[b('Identity uses optimal-gain equality only where valid.','Chỉ dùng đẳng thức gain tối ưu ở bước hợp lệ.'),b('PSD argument holds for arbitrary gain and dimensions.','Lập luận PSD đúng với gain và kích thước bất kỳ.'),b('Separates exact identity, numerical stability and model correctness.','Tách đồng nhất thức chính xác, ổn định số và tính đúng mô hình.')],errors:[b('The simplified covariance formula is not valid for every arbitrary K.','Công thức hiệp phương sai rút gọn không đúng với mọi K bất kỳ.')],repair:[7,69,79,97]},
 {title:b('When standardized innovations are independent','Khi nào innovation chuẩn hóa độc lập'),skills:['proof','transfer'],prompt:b(r`Suppose a correctly specified Gaussian predictor satisfies $Y_t\mid\mathcal F_{t-1}\sim N(m_t,S_t)$, with m_t and positive S_t known from the past. Define Z_t=(Y_t−m_t)/√S_t. Prove Z_t is independent of the past and that the Z_t are IID N(0,1). Then identify what changes if parameters are estimated and plugged in from the past without accounting for parameter uncertainty.`,r`Giả sử dự báo Gaussian đúng thỏa $Y_t\mid\mathcal F_{t-1}\sim N(m_t,S_t)$, m_t và S_t dương được biết từ quá khứ. Đặt Z_t=(Y_t−m_t)/√S_t. Chứng minh Z_t độc lập quá khứ và các Z_t IID N(0,1). Sau đó chỉ ra thay đổi khi tham số được ước lượng từ quá khứ rồi thế vào mà không tính bất định tham số.`),hints:[b('Use conditional probabilities of Borel sets, not zero covariance.','Dùng xác suất có điều kiện của tập Borel, không chỉ hiệp phương sai không.')],solution:[b(r`For Borel B, $P(Z_t\in B\mid\mathcal F_{t-1})=\Phi(B)$, a deterministic standard normal probability. For A∈F_(t−1), multiply by 1_A and integrate to get $P(A\cap\{Z_t\in B\})=P(A)\Phi(B)$.`,r`Với B Borel, $P(Z_t\in B\mid\mathcal F_{t-1})=\Phi(B)$, xác suất chuẩn tắc cố định. Với A∈F_(t−1), nhân 1_A rồi tích phân được $P(A\cap\{Z_t\in B\})=P(A)\Phi(B)$.`),b('Earlier standardized innovations are past-measurable. Apply the factorization recursively to Borel rectangles to get the product joint law; all margins are standard normal. This proof uses the full conditional distribution, not merely conditional variance one.','Innovation chuẩn hóa trước đó đo được theo quá khứ. Lặp phép phân tích xác suất trên các hình chữ nhật Borel được luật tích; mọi biên chuẩn tắc. Chứng minh dùng toàn bộ phân phối có điều kiện, không chỉ phương sai có điều kiện một.'),b('Past-only fitting prevents future leakage but does not make fitted m,S equal the true conditional moments/distribution. Plug-in parameter error can produce nonnormal, dependent residuals; exact IID diagnostics must then be qualified or the full posterior predictive model derived.','Fit chỉ từ quá khứ ngăn rò tương lai nhưng không khiến m,S đã fit bằng moment/phân phối có điều kiện thật. Sai số tham số thế vào có thể tạo phần dư không chuẩn, phụ thuộc; phải giới hạn chẩn đoán IID chính xác hoặc dẫn xuất đủ posterior predictive.')],criteria:[b('Conditional distribution specified and past measurability used.','Nêu phân phối có điều kiện và dùng tính đo được quá khứ.'),b('Proves independence via event factorization, not correlation.','Chứng minh độc lập bằng phân tích biến cố, không bằng tương quan.'),b('Correct distinction between no leakage and correct predictive distribution.','Phân biệt đúng không rò thông tin và phân phối dự báo đúng.')],errors:[b('Estimated parameters being past-measurable is necessary for forecasting but not sufficient for exact calibration.','Tham số ước lượng đo được theo quá khứ cần cho dự báo nhưng chưa đủ hiệu chuẩn chính xác.')],repair:[34,36,57,80]},
 {title:b('Quantify a misspecified observation variance','Định lượng phương sai quan sát bị chỉ định sai'),skills:['derivation','counterexample'],prompt:b(r`True x~N(0,1), y=x+v with v~N(0,4) independent. A filter incorrectly assumes R=1, so uses gain 1/2 and reports posterior variance 1/2. Calculate its actual MSE, the optimal gain/MSE, and the excess MSE. Derive the formula for arbitrary scalar gain k.`,r`Thật sự x~N(0,1), y=x+v, v~N(0,4) độc lập. Filter giả sử sai R=1 nên dùng gain 1/2, báo phương sai hậu nghiệm 1/2. Tính MSE thật, gain/MSE tối ưu và MSE dư. Dẫn xuất công thức cho gain vô hướng k bất kỳ.`),hints:[b('Write x−ky=(1−k)x−kv before taking variances.','Viết x−ky=(1−k)x−kv trước khi lấy phương sai.')],solution:[b(r`Independence gives $MSE(k)=(1-k)^2+4k^2=1-2k+5k^2$. At k=1/2 it is $1/4+1=5/4$, not the reported 1/2.`,r`Độc lập cho $MSE(k)=(1-k)^2+4k^2=1-2k+5k^2$. Tại k=1/2 nó bằng $1/4+1=5/4$, không phải 1/2 đã báo.`),b(r`Complete the square: $MSE(k)=4/5+5(k-1/5)^2$. The optimal gain is 1/5, MSE=4/5; the misspecified excess is $5/4-4/5=9/20$.`,r`Hoàn thành bình phương: $MSE(k)=4/5+5(k-1/5)^2$. Gain tối ưu 1/5, MSE=4/5; phần dư do sai mô hình là $5/4-4/5=9/20$.`),b('A covariance output is conditional on model assumptions. The calculation supplies an exact fixture for the capstone; simulation may check implementation but cannot correct the reported model uncertainty by itself.','Hiệp phương sai xuất ra phụ thuộc giả thiết mô hình. Phép tính cho fixture chính xác của capstone; mô phỏng có thể kiểm tra cài đặt nhưng tự nó không sửa được bất định mô hình đã báo.')],criteria:[b('Correct true noise variance in error decomposition.','Đúng phương sai nhiễu thật trong phân rã sai số.'),b('Optimal gain and all three MSE quantities exact.','Gain tối ưu và ba đại lượng MSE chính xác.'),b('Explains model-conditional covariance and fixture scope.','Giải thích hiệp phương sai theo mô hình và phạm vi fixture.')],errors:[b('Reusing the assumed R in the actual-MSE calculation hides the failure.','Dùng lại R giả định để tính MSE thật sẽ che lỗi.')],repair:[36,79,80,97]},
 {title:b('Risk of selecting the best noisy estimate','Rủi ro chọn ước lượng nhiễu tốt nhất'),skills:['proof','counterexample','transfer'],prompt:b(r`Two candidate procedures have equal true risk μ. Their reported validation estimates are μ+Z1 and μ+Z2 with independent centered integrable noises, not identical a.s. Prove the expected selected minimum is μ−E|Z1−Z2|/2<μ. Explain how this affects choosing a noise-adaptation rule using the same final evaluation period.`,r`Hai phương pháp có rủi ro thật bằng μ. Ước lượng validation được báo là μ+Z1 và μ+Z2 với nhiễu độc lập trung tâm khả tích, không bằng nhau hầu chắc chắn. Chứng minh kỳ vọng cực tiểu được chọn là μ−E|Z1−Z2|/2<μ. Giải thích ảnh hưởng khi chọn luật thích nghi nhiễu bằng chính giai đoạn đánh giá cuối.`),hints:[b('Express min(a,b) using a+b and |a−b|.','Viết min(a,b) bằng a+b và |a−b|.')],solution:[b(r`$\min(a,b)=(a+b-|a-b|)/2$. Substitute a=μ+Z1,b=μ+Z2 and take expectations; integrability follows from that of the noises.`,r`$\min(a,b)=(a+b-|a-b|)/2$. Thế a=μ+Z1,b=μ+Z2 rồi lấy kỳ vọng; khả tích có từ khả tích của nhiễu.`),b(r`Since $P(Z1\ne Z2)>0$, the nonnegative absolute difference has strictly positive expectation. Therefore the selected validation estimate is optimistically biased although both individual estimates were unbiased.`,r`Vì $P(Z1\ne Z2)>0$, hiệu tuyệt đối không âm có kỳ vọng dương chặt. Vì thế ước lượng validation được chọn lệch lạc quan dù từng ước lượng riêng không chệch.`),b('Freeze the adaptation rule using training/validation information, then score all candidates on the same untouched final origins with paired uncertainty. If no untouched data remain, call the result exploratory; re-labeling the same observations cannot restore independence from selection.','Chốt luật thích nghi bằng thông tin train/validation rồi chấm ứng viên trên cùng gốc cuối chưa dùng, với bất định cặp. Nếu không còn dữ liệu chưa dùng, gọi kết quả là khám phá; đổi nhãn cùng quan sát không khôi phục độc lập với lựa chọn.')],criteria:[b('Integrable exact min identity and expectation.','Đồng nhất thức min khả tích và kỳ vọng chính xác.'),b('Strictness condition correctly stated.','Nêu đúng điều kiện bất đẳng thức chặt.'),b('Concrete separation of selection and evaluation without false confirmation.','Tách lựa chọn và đánh giá cụ thể, không xác nhận giả.')],errors:[b('More seeds do not remove selection bias if only the minimum is reported.','Thêm seed không xóa lệch lựa chọn nếu chỉ báo cực tiểu.')],repair:[52,58,82,89]},
 {title:b('Define the capstone mathematical acceptance test','Định nghĩa kiểm tra chấp nhận toán cho capstone'),skills:['transfer','derivation','proof'],prompt:b(r`Construct a local capstone specification comparing a fixed-noise Kalman predictor and a past-only adaptive-noise predictor. It must include a proved identity, a numerical fixture with exact expected values, a counterexample, and a dependent uncertainty target. Give the actual mathematical artifacts, not only file names.`,r`Lập đặc tả capstone cục bộ so sánh Kalman nhiễu cố định và Kalman thích nghi nhiễu chỉ dùng quá khứ. Phải có đồng nhất thức đã chứng minh, fixture số với giá trị mong đợi chính xác, phản ví dụ và đại lượng bất định phụ thuộc. Nêu nội dung toán thật, không chỉ tên file.`),hints:[b('Use the Joseph identity, the wrong-R example and paired loss variance.','Dùng đồng nhất thức Joseph, ví dụ R sai và phương sai loss cặp.')],solution:[b(r`Identity: for optimal K, Joseph covariance equals P−KSKᵀ, with the expansion from e1. Fixture: P=1,R_true=4,H=1 gives K*=1/5,P*=4/5; a wrong assumed R=1 uses K=1/2 and actual MSE 5/4. Assert each exact value independently.`,r`Đồng nhất thức: với K tối ưu, hiệp phương sai Joseph bằng P−KSKᵀ, dùng khai triển ở e1. Fixture: P=1,R_true=4,H=1 cho K*=1/5,P*=4/5; giả sử sai R=1 dùng K=1/2, MSE thật 5/4. Kiểm tra độc lập từng giá trị chính xác.`),b(r`Counterexample: shared latent Z in D_t=Z+ε_t defeats a stationary-only LLN claim. Estimand: μ_D=E[(Y−ŷ_adapt)^2−(Y−ŷ_fixed)^2] in a declared stationary regime. The variance of its sample mean includes all cross-time covariances; a HAC/block method needs conditions from W76–78.`,r`Phản ví dụ: Z ẩn chung trong D_t=Z+ε_t bác bỏ LLN chỉ dựa tính dừng. Đại lượng đích: μ_D=E[(Y−ŷ_adapt)^2−(Y−ŷ_fixed)^2] trong chế độ dừng được nêu. Phương sai trung bình mẫu chứa mọi hiệp phương sai theo thời gian; phương pháp HAC/block cần điều kiện W76–78.`),b('The adaptive Q update at time t may use residuals only through t−1 for scoring y_t. Synthetic regime shifts test mismatch behavior and numerical stability, but the stationary asymptotic theorem is not applied across an unmodeled break. Deliver derivations, fixture results and a limited claim; no trading-return claim follows.','Cập nhật Q thích nghi tại t chỉ dùng residual tới t−1 khi chấm y_t. Chuyển chế độ giả lập kiểm tra sai mô hình và ổn định số, nhưng không áp dụng định lý tiệm cận dừng xuyên điểm gãy chưa mô hình hóa. Bàn giao dẫn xuất, kết quả fixture và kết luận giới hạn; không suy ra lợi nhuận giao dịch.')],criteria:[b('Correct identity and independent exact fixture values.','Đúng đồng nhất thức và giá trị fixture chính xác độc lập.'),b('Counterexample and dependent estimand explicitly specified.','Nêu rõ phản ví dụ và đại lượng đích phụ thuộc.'),b('Adaptation timing and claim scope valid.','Thời điểm thích nghi và phạm vi kết luận hợp lệ.')],errors:[b('A capstone is not validated by running many seeds without a theorem/assumption contract.','Chạy nhiều seed không xác minh capstone nếu thiếu điều kiện định lý/giả thiết.')],repair:[76,77,80,97,98]},
];
add(102,b('Capstone III: covariance stability and honest selection','Capstone III: ổn định hiệp phương sai và lựa chọn có căn cứ'),[97,98,99],
 b(r`P and R are state/observation error covariance matrices; K is a d×m gain. The innovation covariance S=HPHᵀ+R is m×m. The Joseph form retains contributions from independent prior error and observation noise. It is distinct from the covariance of a fitted estimator under misspecification.`,r`P và R là ma trận hiệp phương sai sai số trạng thái/quan sát; K là gain d×m. Hiệp phương sai innovation S=HPHᵀ+R kích thước m×m. Dạng Joseph giữ đóng góp từ sai số tiên nghiệm và nhiễu quan sát độc lập. Nó khác hiệp phương sai của ước lượng đã fit dưới sai mô hình.`),
 b(r`For any gain K, independent mean-zero errors e and v with covariances P,R give $\operatorname{Cov}((I-KH)e-Kv)=(I-KH)P(I-KH)^T+KRK^T\succeq0$.`,r`Với mọi gain K, sai số e và v độc lập trung bình không có hiệp phương sai P,R cho $\operatorname{Cov}((I-KH)e-Kv)=(I-KH)P(I-KH)^T+KRK^T\succeq0$.`),
 b(r`Linearity gives zero updated mean. In the outer-product expansion the two cross terms vanish since E[evᵀ]=0. The remaining terms are the displayed covariance. For any z its quadratic form is the variance of $z^T((I-KH)e-Kv)$, hence nonnegative. No optimal-gain assumption was used.`,r`Tính tuyến tính cho trung bình cập nhật không. Khai triển tích ngoài có hai số hạng chéo biến mất vì E[evᵀ]=0. Hai số hạng còn lại là hiệp phương sai đã nêu. Với mọi z, dạng toàn phương là phương sai của $z^T((I-KH)e-Kv)$ nên không âm. Không dùng giả thiết gain tối ưu.`),
 b(r`Scalar P=1,R=4,H=1,k=1/2 yields (1−k)²P+k²R=5/4. Reporting 1/2 because assumed R=1 confuses assumed covariance with actual risk.`,r`Vô hướng P=1,R=4,H=1,k=1/2 cho (1−k)²P+k²R=5/4. Báo 1/2 vì giả sử R=1 là nhầm hiệp phương sai giả định với rủi ro thật.`),
 b(r`If e=v with variance one and H=1,k=1/2, the updated error is zero, but the independent-noise formula gives 1/2. Correlated noise needs cross terms.`,r`Nếu e=v phương sai một và H=1,k=1/2, sai số cập nhật bằng không, nhưng công thức nhiễu độc lập cho 1/2. Nhiễu tương quan cần số hạng chéo.`),capstone,'a-filter','§4.3 Kalman covariance; Appendix A.1; original misspecification fixtures');
repairWeek(104,102,b('Capstone proof portfolio: reconstruct and repair','Hồ sơ chứng minh capstone: tái dựng và sửa'),capstone,[102]);
